INSERT INTO `blog_article` VALUES ('247', '最新把全网吧干断网工具', '<p>&nbsp;下载链接：<a href=\"http://pan.baidu.com/s/1i4EZ2C1\">http://pan.baidu.com/s/1i4EZ2C1</a> 密码：37ml<br></p><p><br></p><p>酌情使用 亲测有效 无效我也不会发出来的 直接集成到软件里面 大家使用就方便多了&nbsp;</p><p>记住 只干看不惯的网吧 &nbsp;别用自己身份证</p><p>思路</p><pre><code> 首先 准备5块钱 找一个不需要身份证或者小学生居多的网吧下手 为什么我就不多说了 在进入之前请准备好自己的逃跑路线 花4块钱开一个小时的最好包间或者角落 最好没人看的见你的屏幕  剩下一块买瓶矿泉水 熟练的开机 看会QQ空间啥的 准备好软件 矿泉水倒掉半瓶 留半瓶看的更霸气 慢悠悠喝一口 点一下攻击按钮 以最快速度关闭显示器 然后淡淡定定的走出网吧 在出门的同时 伴随你的是一群人大喊的 “我艹 网管断网了！” 低调冷静的走到网吧门口 撒腿就跑 最后用两个字形容 TM刺激\r\n</code></pre>', 'https://feilongwl.cn/Public/Uploads/2017-04-29/5904a723d82c8.png', '1', '25', '1493477798', '1493564601', '1680', '0', '', '1', '0', '', '', '', '1');
INSERT INTO `blog_article` VALUES ('261', '5.21助力 表白神器 奉上', '<p>电脑版视频制作：软件可能存在一些bug 不准备修复了 凑合用 加载有很多视频可以生成哦</p><p><b>下载地址&nbsp;<a href=\"http://pan.baidu.com/s/1o8FM8MA\" target=\"_blank\">http://pan.baidu.com/s/1o8FM8MA</a></b></p><p><img alt=\"QQ截图20170520230146.jpg\" src=\"https://feilongwl.cn/Public/Uploads/2017-05-20/59205c101845e.jpg\" width=\"865\" height=\"719\"><br></p><p><br></p><p>安卓表白网页生成软件 ：</p><p><img src=\"C:/Users/Administrator/AppData/Local/YNote/data/qq3387EEE08C84E888F530CB377C031273/30edfeff93a54fabbd1f3a20e7316b9c/clipboard.png\" alt=\"\"><br></p><p><img alt=\"clipboard.png\" src=\"https://feilongwl.cn/Public/Uploads/2017-05-20/59205cb3c1be9.png\" width=\"415\" height=\"749\"><br></p><p><br></p><p>广告词&nbsp;</p><p>安卓版&nbsp;各种网页设计在线生成</p><p>收徒网&nbsp;引导页&nbsp;表白网&nbsp;祝福网&nbsp;等等 </p><p><span style=\"font-size: 15px;\">款式蛮多的，自己不需要域名和空间就可以一键生成&nbsp;</span></p><p><span style=\"font-size: 15px;\">5.20本人修复版本 原来流出去的早就黄了 </span></p><p><span style=\"font-size: 15px;\">大家珍惜这个版本   独家的哦  </span></p><p>明天521了，赶紧弄一个装逼表白网给你心爱的人瞧瞧吧！</p><p>获取能得到她/他的感动呢？&nbsp;也可以拿去卖软件</p><p>================</p><p>下载地址：<span style=\"color: rgb(0, 56, 132);\"><a href=\"http://pan.baidu.com/s/1kV1F1bx\">http://pan.baidu.com/s/1kV1F1bx</a></span></p><p><br></p><p>就这些哦</p>', 'https://feilongwl.cn/Public/Uploads/2017-05-20/59205c101845e.jpg', '1', '25', '1495293122', '1495293122', '1156', '0', '', '0', '0', '', '', '', '1');
