INSERT INTO `blog_article` VALUES ('263', '网络安全法今日上线 以后要怂了', '<p><span style=\"font-size: 15px;\">现在网络免费资源越来越不好搞了，什么原因造成的呢？</span></p><p><span style=\"font-size: 15px;\">当然跟国内的制度有关了，最近热传《网络安全法》将于2017年6月1日正工颁布实施了。</span></p><p><span style=\"font-size: 15px;\">但是这个《网络安全法》对于免费资源有啥影响呢？听飞龙给各位细细讲解。<br></span></p><p><span style=\"font-size: 15px;\"><img src=\"http://www.xiaodao.la/upload/1/146486/images/20170601/20170601081451985198.jpg\" alt=\"\" width=\"100%\" height=\"100%\">&nbsp;</span></p><p><span style=\"font-size: 15px;\">QQ群都在搞实名制了，百度网盘也要求实名制，淘宝不管是购物、开店都需要实名认证。<br></span></p><p><span style=\"font-size: 15px;\">从BAT巨头互联网公司的实名制政策来看，在国内互联网用户实名制是趋势。</span></p><p><span style=\"font-size: 15px;\">各家互联网公司要求实名制，造成领取一个免费的资源，都需要拿自己的实名信息来做交换。</span></p><p><span style=\"font-size: 15px;\"><img src=\"http://www.xiaodao.la/upload/1/146486/images/20170601/2017060108150941941.jpg\" alt=\"\" width=\"100%\" height=\"100%\">&nbsp;</span></p><p><span style=\"font-size: 15px;\">不实名行不行？答案是不行！现在国家更是颁布出《网络安全法》，来规避网络违法行为。</span></p><p><span style=\"font-size: 15px;\">因此，网络实名制是势在必行的，劝解各位认清实现慢慢接受，不要在搞违法的事。</span></p><p><span style=\"font-size: 15px;\">来说几条比较值得关注的法规：</span></p><p><span style=\"font-size: 15px;\">《网络安全法》第二十一条规定：网络数据泄露或者被窃取、篡改，属违法行为；<br></span></p><p><span style=\"font-size: 15px;\">《网络安全法》第二十四条规定：用户需提交真实有效实名认证信息；<br></span></p><p><span style=\"font-size: 15px;\">《网络安全法》第二十五条规定：运营者必须有能力提供网络安全事件的应急预案；</span></p><p><span style=\"font-size: 15px;\">《网络安全法》第四十二条规定：网络运营者如何保护用户信息的完整性，不被泄露、窃取或篡改。</span></p><p><span style=\"font-size: 15px;\">关于更多《网络安全法》条款请参见：<a href=\"http://t.cn/RfzgNGT\" target=\"_blank\">http://t.cn/RfzgNGT</a></span></p><p><span style=\"font-size: 15px;\">【我也很绝望啊，但又能怎么样，以后做个良民吧，更新得差点就差点了】</span></p><p><span style=\"font-size: 15px;\">大家记住千万别倒卖个人信息，超过50条，就要去吃牢饭了，这次重点是这个。</span></p>', 'http://www.xiaodao.la/upload/1/146486/images/20170601/20170601081451985198.jpg', '1', '3', '1496290758', '1496290840', '898', '0', '', '0', '0', '', '', '', '1');
INSERT INTO `blog_article` VALUES ('264', '一大堆经典PC单机游戏 玩的存', '<p>飞龙 QQ 467256306 &nbsp;福利群：623406246</p><p>以前发过不少合集，不过都被度盘给和谐了，今天在分享一波，需要的存！&nbsp;</p><p>全部是下载解压打开即玩的，自己也不用费力网上去到处找哪个能玩的了。&nbsp;</p><p>缺少DLL文件,源文件损坏 &nbsp;（看此视频）<a href=\"http://pan.baidu.com/s/1boZYxIZ\" rel=\"nofollow\">http://pan.baidu.com/s/1boZYxIZ</a>&nbsp;</p><p>游戏安装必备必装软件：<a href=\"http://pan.baidu.com/s/1c25PmTE\" rel=\"nofollow\">http://pan.baidu.com/s/1c25PmTE</a>&nbsp;</p><p>尼尔机械纪元：<a href=\"http://pan.baidu.com/s/1bpiYyCn\" rel=\"nofollow\">http://pan.baidu.com/s/1bpiYyCn</a> 密码：7w24&nbsp;</p><p>逃生2：<a href=\"http://pan.baidu.com/s/1slRQPvn\" rel=\"nofollow\">http://pan.baidu.com/s/1slRQPvn</a> 密码：ebld</p><p>&nbsp;</p><p>质量效应4：<a href=\"http://pan.baidu.com/s/1gfzKnYz\" rel=\"nofollow\">http://pan.baidu.com/s/1gfzKnYz</a> 密码：u2iw</p><p>&nbsp;</p><p>正当防卫3：<a href=\"http://pan.baidu.com/s/1slfLlKh\" rel=\"nofollow\">http://pan.baidu.com/s/1slfLlKh</a> 密码：qht8</p><p>&nbsp;</p><p>GTA5(1.36)：<a href=\"http://pan.baidu.com/s/1pLRUokV\" rel=\"nofollow\">http://pan.baidu.com/s/1pLRUokV</a> 密码：qnwn</p><p>&nbsp;</p><p>GTA5(1.33)：<a href=\"http://pan.baidu.com/s/1eS8897G\" rel=\"nofollow\">http://pan.baidu.com/s/1eS8897G</a> 密码：9hyl</p><p>&nbsp;</p><p>使命召唤13：<a href=\"http://pan.baidu.com/s/1eSccZHC\" rel=\"nofollow\">http://pan.baidu.com/s/1eSccZHC</a> 密码：65n0</p><p>&nbsp;</p><p>三国志13：<a href=\"http://pan.baidu.com/s/1i5eEMI5\" rel=\"nofollow\">http://pan.baidu.com/s/1i5eEMI5</a> 密码：gbst&nbsp;</p><p>三国志13威力加强版：<a href=\"http://pan.baidu.com/s/1sllSeIx\" rel=\"nofollow\">http://pan.baidu.com/s/1sllSeIx</a> 密码：lw6s&nbsp;</p><p>杀手6：<a href=\"http://pan.baidu.com/s/1mhQxoxi\" rel=\"nofollow\">http://pan.baidu.com/s/1mhQxoxi</a> 密码：v4a0&nbsp;</p><p>无双大蛇Z：<a href=\"http://pan.baidu.com/s/1eRJMatG\" rel=\"nofollow\">http://pan.baidu.com/s/1eRJMatG</a> 密码：3xfo&nbsp;</p><p>奇异人生：<a href=\"http://pan.baidu.com/s/1i4NdIp3\" rel=\"nofollow\">http://pan.baidu.com/s/1i4NdIp3</a> 密码：nwqq</p><p>&nbsp;</p><p>狂战传说：<a h