INSERT INTO `blog_article` VALUES ('286', '安卓QQ6.6.8谷歌蓝V2版 保证你会爱上它', '<p><img src=\"http://www.xiaodao.la/upload/1/146486/images/20170204/20170204172356225622.jpg\" alt=\"\">&nbsp;</p><p><img src=\"http://www.xiaodao.la/upload/1/146486/images/20170204/20170204172362786278.jpg\" alt=\"\">&nbsp;</p><p><img src=\"http://www.xiaodao.la/upload/1/146486/images/20170205/20170205003549004900.jpg\" alt=\"\">&nbsp;</p><p><span style=\"font-size: 15px;\"><strong>用不习惯官方版手机QQ？想用清爽版？那么你可以继续往下看</strong></span></p><p><span style=\"font-size: 15px;\"><strong>修改内容：</strong></span></p><p><span style=\"font-size: 15px;\">1、更换底栏、未读消息提示、联系人页、长按编辑弹窗、气泡、聊天输入框、小工具栏等图标<br></span></p><p><span style=\"font-size: 15px;\">2、联系人页+按钮移至消息页右下方，并改为甜甜私房猫</span><span style=\"font-size: 15px;\">（具体自行体验）</span></p><p><span style=\"font-size: 15px;\">3、修改启动图、清新侧栏布局，添加装扮入口<br></span></p><p><span style=\"font-size: 15px;\">4、多处背景透明去线条处理，更加美观<br></span></p><p><span style=\"font-size: 15px;\">5、去除三界面顶部的“MaterialQQ<br></span></p><p><span style=\"font-size: 15px;\">6、添加聊天背景（可在 侧滑-主题 更换）<br></span></p><p><span style=\"font-size: 15px;\">7、替换QQ国际版气泡，解决发图时图片不居中的问题<br></span></p><p><span style=\"font-size: 15px;\">8、更改新消息提示图标，解决在白色背景下难以分辨的问题。<br></span></p><p><span style=\"font-size: 15px;\">9、增加官方侧滑样式，美化部分素材、修正颜色<br></span></p><p><span style=\"font-size: 15px;\"><strong>底包特点：</strong><br></span></p><p><span style=\"font-size: 15px;\">去气泡</span></p><p><span style=\"font-size: 15px;\">去字体</span></p><p><span style=\"font-size: 15px;\">去字体特效<br></span></p><p><span style=\"font-size: 15px;\">去表情推荐（如果还存在请卸载重装）<br></span></p><p><span style=\"font-size: 15px;\">去表情联想<br></span></p><p><span style=\"font-size: 15px;\"><span style=\"color: rgb(229, 51, 51);\"><strong>自带防撤回（与框架不冲突）</strong></span><br></span></p><p><span style=\"font-size: 15px;\">去后台自启<br></span></p><p><span style=\"font-size: 15px;\">去更新检查<br></span></p><p><span style=\"font-size: 15px;\">免核心破解直装<br></span></p><p><span style=\"font-size: 15px;\">去部分应用唤醒<br></span></p><p><span style=\"font-size: 15px;\">去WIFI状态下自动下载更新包<br></span></p><p><span style=\"font-size: 15px;\">去霸占内存的毒瘤服务<br></span></p><p><span style=\"font-size: 15px;\">禁止后台常驻（不影响正常接受消息，只是可以彻底杀掉后台）<br></span></p><p><span style=\"font-size: 15px;\">去聊天窗口“为TA设置特别消息提示音”提示<br></span></p><p><span style=\"font-size: 15px;\">去聊天窗口“想要打字更快，试试搜狗输入法吧。”提示<br></span></p><p><span style=\"font-size: 15px;\">去小红点和new提示<br></span></p><p><span style=\"font-size: 15px;\">设置界面小改<br></span></p><p><span style=\"font-size: 15px;\">去除动态界面“附近”、“兴趣部落”<br></span></p><p><span style=\"font-size: 15px;\">去除设置“空间清理”内的“深度储存清理”<br></span></p><p><span style=\"font-size: 15px;\">去CoreService服务<br></span></p><p><span style=\"font-size: 15px;\">去KernelService服务<br></span></p><p><span style=\"font-size: 15px;\">去兴趣号相关服务<br></span></p><p><span style=\"font-size: 15px;\">去QQWIFI相关服务<br></span></p><p><span style=\"font-size: 15px;\">去深度清理相关服务（腾讯手机管家推广）</span></p><p><span style=\"font-size: 15px;\">去安全检查相关服务（腾讯手机管家推广）<br></span></p><p><span style=\"font-size: 15px;\">志愿者寻人寻物计划相关服务</span></p><p>&nbsp;链接:&nbsp;<a href=\"https://pan.baidu.com/s/1nvRUaFJ\">https://pan.baidu.com/s/1nvRUaFJ</a>&nbsp;密码:&nbsp;nt29&nbsp;<a href=\"https://pan.baidu.com/s/1nvRUaFJ\" target=\"_self\">点击下载</a></p>', 'https://feilongwl.cn/Public/Uploads/2017-02-05/58968b568be34.jpg', '1', '22', '1498031370', '1498031370', '1205', '0', '', '0', '0', '', '', '', '1');
INSERT INTO `blog_article` VALUES ('289', '渗透测试神器Burp Suite v1.6.37', '<p>图片为&nbsp;<span style=\"font-size: medium;\"><span style=\"color: rgb(255, 0, 0);\">1.6.27的配图</span></span></p><p><span style=\"font-size: medium;\"><span style=\"color: rgb(255, 0, 0);\"><br></span></span></p><p>众所周知，Burp Suite是响当当的web应用程序渗透测试集成平台。从应用程序攻击表面的最初映射和分析，到寻找和利用安全漏洞等过程，所有工具为支持整体测试程序而无缝地在一起工作。</p><p>平台中所有工具共享同一robust框架，以便统一处理HTTP请求、持久性、认证、上游代理、日志记录、报警和可扩展性。Burp Suite允许攻击者结合手工和自动技术去枚举、分析、攻击Web应用程序。</p><p>最近发现Burp老的license都过期了 然后给大家推荐了此文</p><p>关于更详细介绍 Burpsuite ：<a href=\"http://baike.baidu.com/link?url=UEWscTPI8aHB3aQ33Hrl2l6xs2m64Uv5mpKdqUchqQcbTtWWsHv96qSd4vOrWjwdloN2h_wWh9y-GgcrHyQV4K\" target=\"_blank\"><span style=\"font-size: small;\">http://baike.baidu.com/link?url= ... 2h_wWh9y-GgcrHyQV4K</span></a></p><p><span style=\"color: rgb(68, 68, 68);\">拦截代理（Proxy），你可以检查和更改浏览器与目标应用程序间的流量；可感知应用程序的网络爬虫（Spider），它能完整的枚举应用程序的内容和功能；高级扫描器，执行后它能自动地发现web应用程序的安全漏洞；入侵测试工具（Intruder），用于执行强大的定制攻击去发现及利用不同寻常的漏洞；重放工具（Repeater），一个靠手动操作来触发单独的HTTP 请求，并分析应用程序响应的工具；会话工具（Sequencer），用来分析那些不可预知的应用程序会话令牌和重要数据项的随机性的工具；解码器，进行手动执行或对应用程序数据者智能解码编码的工具；扩展性强，可以让你加载Burp Suite的扩展，使用你自己的或第三方代码来扩展Burp Suit的功能。</span></p><p><span style=\"color: rgb(68, 68, 68);\">&nbsp;</span></p><p><span style=\"color: rgb(68, 68, 68);\">Burp Suite的重要特性</span></p><p><span style=\"color: rgb(68, 68, 68);\">拦截代理（Proxy），你可以检查和更改浏览器与目标应用程序间的流量；</span></p><p><span style=\"color: rgb(68, 68, 68);\">可感知应用程序的网络爬虫（Spider），它能完整的枚举应用程序的内容和功能；</span></p><p><span style=\"color: rgb(68, 68, 68);\">高级扫描器，执行后它能自动地发现web应用程序的安全漏洞；</span></p><p><span style=\"color: rgb(68, 68, 68);\">入侵测试工具（Intruder），用于执行强大的定制攻击去发现及利用不同寻常的漏洞；</span></p><p><span style=\"color: rgb(68, 68, 68);\">重放工具（Repeater），一个靠手动操作来触发单独的HTTP 请求，并分析应用程序响应的工具；</span></p><p><span style=\"color: rgb(68, 68, 68);\">会话工具（Sequencer），用来分析那些不可预知的应用程序会话令牌和重要数据项的随机性的工具；</span></p><p><span style=\"color: rgb(68, 68, 68);\">解码器，进行手动执行或对应用程序数据者智能解码编码的工具；</span></p><p><span style=\"color: rgb(68, 68, 68);\">扩展性强，可以让你加载Burp Suite的扩展，使用你自己的或第三方代码来扩展Burp Suit的功能。</span></p><p><span style=\"color: rgb(255, 0, 0);\">burp: 下载地址&nbsp;</span><a href=\"http://pan.baidu.com/s/1jGOu1N4\" target=\"_blank\">http://pan.baidu.com/s/1jGOu1N4</a></p><p><span style=\"color: rgb(139, 0, 0);\">本程序需要设置 JAVA运行环境&nbsp;<br><br>jdk32位 下载&nbsp;<a href=\"http://www.uzzf.com/soft/395.html\" target=\"_blank\"><span style=\"font-size: small;\">http://www.uzzf.com/soft/395.html</span></a><br><br>jdk64位 下载&nbsp;<span style=\"color: rgb(51, 102, 153); font-size: small;\"><a href=\"http://www.uzzf.com/soft/77216.html\" target=\"_blank\">http://www.uzzf.com/soft/77216.html</a></span></span></p>', 'https://feilongwl.cn/Public/Uploads/2017-02-03/589486c42b869.png', '1', '27', '1498031428', '1498031428', '1168', '0', '', '0', '0', '', '', '', '1');
INSERT INTO `blog_article` VALUES ('290', '三个版本中国菜刀（官网公布）', '<h3 style=\"margin-left: 0px;\">菜刀这款经典的工具我用过的就有三个版本&nbsp;</h3><p>-----------------------------------------------------------------</p><p><span style=\"color: rgb(0, 153, 255);\">一个是&nbsp;caidao-20100928&nbsp;caidao-20111116 caidao-20141213</span></p><p><span style=\"color: rgb(0, 153, 255);\">网上很多菜刀都被人植入了后门大家用着肯定不放心 所以我就搜集了官方版本 2014官网有下载地址</span></p><p><span style=\"color: rgb(0, 153, 255);\">2011的已经没有了，我在IT什么网站下载了一个 验证了MD5和官方的一样大家放心使用&nbsp;</span></p><p><span style=\"color: rgb(0, 153, 255);\">PS：MD5效验工具下载地址&nbsp;</span><span style=\"color: rgb(0, 153, 255);\"><a href=\"http://www.xiaozhe520.com/news/?144.html\" target=\"_blank\">http://www.xiaozhe520.com/news/?144.html</a>&nbsp;不放心大家可以去验证~</span></p><p>----------------------------------------------------------------</p><p><span style=\"color: rgb(0, 153, 0);\">(chopper.exe)md5各版本校验码:&nbsp;</span></p><p><span style=\"color: rgb(0, 153, 0);\">20111116 =&gt; 5001ef50c7e869253a7c152a638eab8a</span></p><p><span style=\"color: rgb(0, 153, 0);\">20141213 =&gt; 4b4a956b9c7dc734f339fa05e4c2a990&nbsp;<span style=\"color: rgb(85, 85, 85);\">这款2014的菜刀功能没什么突破～waf该拦还是拦～想吐槽的是执行命令好歹多添加几个函数～单单proc_open也太随意了～</span></span></p><p><span style=\"color: rgb(0, 153, 0);\">&nbsp;</span></p><p><span style=\"color: rgb(0, 153, 0);\">2010的官方没有公布MD5我也没找到 抱歉了~~</span></p><p>----------------------------------------------------------------</p><p><span style=\"color: rgb(51, 0, 153);\">中国菜刀用途十分广泛，是一款专业的网站管理软件，支持多种语言，小巧实用，用途广泛，使用方便，据说是一位中国军人退伍之后的作品。</span><br></p><p><span style=\"color: rgb(51, 0, 153);\">之前国外安全公司Fireeye对这款工具进行了详细的剖析，也可以说是一部非常nice的菜刀使用教程：</span></p><p><a href=\"http://www.freebuf.com/articles/web/11687.html\" target=\"_blank\"><span style=\"color: rgb(51, 0, 153);\">《系列一：</span><span style=\"font-size: 1em; color: rgb(51, 0, 153);\">Fireeye技术剖析中国菜刀》</span></a><span style=\"font-size: 1em;\"><a href=\"http://www.freebuf.com/articles/web/12064.html\" target=\"_blank\"><span style=\"color: rgb(51, 0, 153);\">《系列二：Fireeye技术剖析中国菜刀》</span></a></span></p><p><span style=\"color: rgb(88, 88, 88);\"><span style=\"color: rgb(51, 0, 153);\">评黑客利器——中国菜刀：<a href=\"http://www.xiaozhe520.com/news/?114.html\" target=\"_blank\">http://www.xiaozhe520.com/news/?114.html</a></span></span></p><p>---------------------------------------------------------------------------</p><p><a href=\"http://www.xiaozhe520.com/news/?178.html\" target=\"_blank\"><span style=\"color: rgb(255, 0, 0);\">caidao-</span><span style=\"color: rgb(255, 0, 0);\">20100928 下载</span></a></p><p><span style=\"color: rgb(0, 0, 0);\"><span style=\"color: rgb(0, 153, 204);\"><a href=\"http://pan.baidu.com/s/1hqH00RE\" target=\"_blank\"><span style=\"color: rgb(255, 0, 0);\">caidao-20111116 下载</span></a></span></span></p><p><span style=\"color: rgb(0, 0, 0);\"><span style=\"color: rgb(0, 102, 204);\"><a href=\"http://pan.baidu.com/s/1ntJsfYL\" target=\"_blank\"><span style=\"color: rgb(255, 0, 0);\">caidao-20141213 &nbsp;下载</span></a></span></span></p><p><span style=\"color: rgb(88, 88, 88);\"><span style=\"color: rgb(0, 51, 204);\"><a href=\"http://www.xiaozhe520.com/news/?204.html\" target=\"_blank\"><span style=\"font-size: 18px; color: rgb(255, 0, 0);\">移动菜刀 &nbsp; &nbsp; &nbsp;下载</span></a></span></span></p>', 'https://feilongwl.cn/Public/Uploads/2017-02-03/589486dfc612a.png', '1', '27', '1498031456', '1498031456', '2478', '0', '', '0', '0', '', '', '', '1');
INSERT INTO `blog_article` VALUES ('291', '各大组织渗透工具包', '<p>例如1937网军公盟 &nbsp; &nbsp;法克论坛 &nbsp;江南网盟 &nbsp;日月神教&nbsp;</p><p>主体内容（根据常规渗透测试流程定制）</p><p>1. &nbsp;综合扫描</p><p>2. &nbsp;目录检测</p><p>3. &nbsp;注入检测</p><p>4. &nbsp;旁注与c段</p><p>5. &nbsp;抓包改包</p><p>6. &nbsp;webshell</p><p>7. &nbsp;提权工具</p><p>8. &nbsp;arp嗅探</p><p>7. &nbsp;社会工程</p><p>8. &nbsp;破解工具</p><p>9. &nbsp;字典相关</p><p>10. 痕迹清理</p><p>11. 漏洞利用</p><p>12. 后门程序</p><p>13. 其他工具</p><p>14. 渗透学习</p><p>工具细节：</p><p>1.综合检测</p><p>appscan、burp、JSky、safe3wvs、苹果FTP批量扫描工具、WebCruiser、WebSploit Toolkit V.1.9</p><p>wvs、x站神器3.7、x站神器3.7、cv6、百度新闻源挖掘机</p><p>2.目录检测</p><p>chrome后台扫描插件、Pker多线程后台极速扫描工具、WebRobot、WebScan、Wordpress爆路径工具</p><p>wwwscan三个版本（单个、批量、扫备份）、清凉扫描</p><p>3.注入检测</p><p>COOKIE注入工具、Havij、HDSI3.0、NBSI、Oracle_反弹注入工具v1.0、SqlMap免Python环境绿色版</p><p>sqlmap中文包、穿山甲Pangolin、穿山甲Pangolin、河马MySQL注入工具、河马PostgreSQL注入工具</p><p>河马SQLServer注入工具、明小子、手工注入辅助工具、注入中转、GetWebShell增强版、啊d注入工具</p><p>mysql注入辅助程序、小葵多功能转换工具</p><p>4.旁站与c段</p><p>Happy工具箱、Layer、python二级域名批量采集脚本、python抓取谷歌链接工具、长安刺客旁注杀手</p><p>超级旁注、御剑1.5、御剑后台扫描珍藏版、御剑无字典大小限制1937版、3EST 旁注扫描器</p><p>T00ls内部旁注扫描器(需要.net环境)、二级域名爆破工具、鬼哥旁注C段利器</p><p>5.抓包该包</p><p>COOKIES browser、MatriXay1073、smsniff、WSockExpert、WSockExpert_Cn、Fiddler2原版</p><p>HttpAnalyzerFullTrial_V6、WSExplorer 1.3、网络抓包工具</p><p>6.webshell</p><p>ASP马、aspx马、aspx一句话及客户端、cfm马、cgi马、jsp马、php马、war马、两用一句话图片马</p><p>数据库解压、中国菜刀（最新过狗2013-12-20）、一句话大全</p><p>7.提权工具</p><p>hash读取、无net提权、巴西烤肉、lxc、linux、iis、exp大全、端口转发、3389大全、dll、udf</p><p>nc、lpk、星外、s-u、无组件提权</p><p>8.arp嗅探</p><p>Arp EMP v1.0、cain_v4.9汉化版、MAC地址扫描器、NetFuke、幻境网盾3.7、ARPKiller.exe、</p><p>嗅探马</p><p>9.社会工程</p><p>EMailSearch、MB社工辅助工具包、theHarvester-免py环境版、社工利器-手机信息查询、身份证查询</p><p>邮件伪造、MaltegoInstaller-v202-CE</p><p>10.破解工具</p><p>各种数据库破解、密文破解、webshell破解</p><p>11.字典相关</p><p>3389字典、idc机房字典、字典生成器</p><p>12.痕迹清理</p><p>cleaniis、CleanIISLog、clearlogs、IE记录清理、常用入侵清除器、清除IIS日志logcleaner1.0</p><p>日志清除器、无影无踪4.4、组策略清除工具1.1</p><p>13.漏洞利用</p><p>dedecms5.7、Fckeditor综合利用工具、struts2 漏洞利用工具、撸大师1.7、Discuz! X Getshell</p><p>IIS写权限利用工具、phpcms利用工具</p><p>14.后门程序</p><p>LPK2.0、shift后门、T00ls Lpk Sethc v4、T00ls_Lpk_Sethc_v3、不死帐号、截取3389、lpk sethc v4</p><p>全盘感染shift后门、添加超级隐藏账户、隐藏后门 除非重装、最新shift后门</p><p>15.其他工具</p><p>Converter-zh_CN、HconSTF_v0.4_portable、putty、SQL连接、数据库浏览器、Codeeer Explorer</p><p>OWASP Mantra - Armada Win、鬼哥多功能浏览器、1937专用记事本、键盘记录器</p><p><img alt=\"各大组织渗透工具包\" src=\"http://www.xiaozhe520.com/xz.jpg\">&nbsp;提取密码：krqb</p>', 'https://feilongwl.cn/Public/Uploads/2017-02-03/58948717408ad.png', '1', '27', '1498031478', '1498031478', '2137', '0', '', '0', '0', '', '', '', '1');
INSERT INTO `blog_article` VALUES ('292', '8.9 勋章墙破解补丁 by 飞龙', '<p>&nbsp;8.9&nbsp;勋章墙破解补丁&nbsp;一键加速QQ等级成长天数&nbsp;&nbsp;效果请看图&nbsp;软件已上传至百度云盘&nbsp;<img src=\"file:///C:/Users/Administrator/AppData/Roaming/Tencent/QQ/Temp/%W@GJ$ACOF(TYDYECOKVDYB.png\"><a href=\"http://pan.baidu.com/s/1jHZosa6\">http://pan.baidu.com/s/1jHZosa6</a>&nbsp;<img alt=\"DZG4C5X3U_9XBO}~]R0_LIV.jpg\" src=\"http://feilongwl.cn/Public/Uploads/2017-03-26/58d697bd528f4.jpg\" width=\"1102\" height=\"436\"><br></p><p><span style=\"font-size: x-large;\">&nbsp;8.9&nbsp;勋章墙破解补丁&nbsp;一键加速QQ等级成长天数&nbsp;&nbsp;效果请看图&nbsp;软件已上传至百度云盘&nbsp;<img src=\"file:///C:/Users/Administrator/AppData/Roaming/Tencent/QQ/Temp/%W@GJ$ACOF(TYDYECOKVDYB.png\"><a href=\"http://pan.baidu.com/s/1jHZosa6\" target=\"_blank\">http://pan.baidu.com/s/1jHZosa6&nbsp;</a></span></p>', 'https://feilongwl.cn/Public/Uploads/2017-03-26/58d697b8ae1c4.jpg', '1', '22', '1498031489', '1498031489', '1090', '0', '', '0', '0', '', '', '', '1');
INSERT INTO `blog_article` VALUES ('293', '101款精典黑客小工具使用说明', '<p>webadv 针对iis+sp3的溢出成功率很高(溢出后system权限!) *&nbsp;ipscan 大范围网段快速ipc$猜解&nbsp;</p><p>svc 远程安装/删除win2k服务&nbsp;</p><p>3389.vbs 远程安装win2k终端服务不需i386&nbsp;</p><p>arpsniffer arp环境sniffer(需要winpcap2.1以上) *&nbsp;</p><p>ascii 查询字符和数字ascii码(常用来对url编码用以躲避ids或脚本过滤)&nbsp;</p><p>ca 远程克隆账号&nbsp;</p><p>cca 检查是否有克隆账号&nbsp;</p><p>cgi-backdoor 几个cgi木马(十多种利用最新漏洞的web脚本后门，涵盖jsp,php,asp,cgi等等) *&nbsp;</p><p>crackvnc 远程/本地破解winvnc密码(本地破用-W参数)&nbsp;</p><p>pass.dic 密码字典&nbsp;</p><p>debploit win2k+sp2配置最佳权限提升工具&nbsp;</p><p>fpipe 端口重定向工具&nbsp;</p><p>fscan superscan命令行版本(可定义扫描时的源端口并支持udp端口扫描) *&nbsp;</p><p>hgod04 ddos攻击器&nbsp;</p><p>idahack ida溢出&nbsp;</p><p>idq.dll 利用isapi漏洞提升权限(对sp0+sp1+sp2都非常有效，也是很棒的web后门)&nbsp;</p><p>IIS idq溢出&nbsp;</p><p>inst.zip 指定程序安装为win2k服务 *&nbsp;</p><p>ip_mail.rar 发送主机动态IP的软件 *&nbsp;</p><p>ipc.vbs 不依赖ipc$给远程主机开telnet&nbsp;</p><p>ispc.exe idq.dll连接客户端&nbsp;</p><p>Keyghost.zip 正版键盘记录器&nbsp;</p><p>log.vbs 日志清除器(远程清除不依赖ipc$)&nbsp;</p><p>md5.pl 论坛md5加密密码破解器&nbsp;</p><p>msadc.pl winnt的msadc漏洞溢出器 *&nbsp;</p><p>MsSqlHack mssql溢出程序1&nbsp;</p><p>mysql-client mysql客户端&nbsp;</p><p>Name.dic 最常用的中国人用户名(看看你常用的用户名在不在里面)&nbsp;</p><p>PassSniffer 大小仅3kb的非交换机sniffer软件 *&nbsp;</p><p>psexec 通过ipc管道直接登录主机&nbsp;</p><p>pskill 杀进程高手:)&nbsp;</p><p>pslist 列进程高手:)&nbsp;</p><p>rar 命令行下的中文版winrar(功能相当全面) *&nbsp;</p><p>reboot.vbs 远程重启主机的脚本&nbsp;</p><p>sdemo.zip 巨好的屏幕拍摄的录像软件&nbsp;</p><p>shed 远程查找win9x的共享资源&nbsp;</p><p>sid 用sid列用户名&nbsp;</p><p>SkServerGUI snake多重代理软件&nbsp;</p><p>SkSockServer snake代理程序&nbsp;</p><p>SMBCrack 超快的ipc破解软件（适合破一台机)&nbsp;</p><p>socks 利用这工具安装木马，即使网关重新低格硬盘木马也在嘿嘿 *&nbsp;</p><p>SocksCap 把socks5代理转化为万能代理&nbsp;</p><p>SPC.zip 可以直接显示出远程win98共享资源密码的东东 *&nbsp;</p><p>WMIhack 基于WMI服务进行账号密码的东东(不需要ipc)&nbsp;</p><p>skmontor snake的注册表监视器（特酷的)&nbsp;</p><p>sql1.exe mssql溢出程序2&nbsp;</p><p>sql2.exe mssql溢出程序3&nbsp;</p><p>SqlExec mssql客户端&nbsp;</p><p>SuperScan GUI界面的优秀扫描器&nbsp;</p><p>syn syn攻击第一高手&nbsp;</p><p>upx120 特好的压缩软件，常用来压缩木马躲避杀毒软件&nbsp;</p><p>wget 命令行下的http下载软件&nbsp;</p><p>Win2kPass2 win2k的密码大盗&nbsp;</p><p>Winnuke 攻击rpc服务的软件(win2ksp0/1/2/3+winnt+winxp系统不稳定)&nbsp;</p><p>smbnuke 攻击netbios的软件(win2ksp0/1/2/3+winnt+winxp系统死机)&nbsp;</p><p>WinPcap_2_3 nmap,arpsniffer等等都要用这个&nbsp;</p><p>WinPcap_2_3_nogui.exe 无安装界面自动安装的WinPcap_2_3（命令行版) *&nbsp;</p><p>scanbaby2.0 能对80%的mail服务利用漏洞列账号密码破解(超酷哦，去看rfc里有mail弱点说明) *&nbsp;</p><p>SuperDic_V31 非常全面的黑客字典生成器&nbsp;</p><p>Getadmin win2k+sp3配置的权限提升程序(不错!!!) *&nbsp;</p><p>whoami 了理自己的权限&nbsp;</p><p>FsSniffer 巨好的非交换机sniffer工具&nbsp;</p><p>twwwscan 命令行下巨好的cgi扫描器&nbsp;</p><p>TFTPD32 给远方开tftp服务的主机传文件(当然要有个shell)&nbsp;</p><p>RangeScan 自定义cgi漏洞的GUI扫描器&nbsp;</p><p>pwdump2 本地抓winnt/2k密码散列值(不可缺)&nbsp;</p><p>pwdump3 远程抓winnt/2k密码散列值(不可缺)&nbsp;</p><p>procexpnt 查看系统进程与端口关联(GUI界面) *&nbsp;</p><p>nc 已经不是简单的telnet客户端了&nbsp;</p><p>CMD.txt 有什么cmd命令不懂就查查它 *&nbsp;</p><p>fport 命令行下查看系统进程与端口关联(没有GUI界面的procexpnt强)&nbsp;</p><p>BrutusA2 全功能的密码破解软件,支持telnet,ftp,http等服务的口令破解&nbsp;</p><p>cmd.reg 文件名自动补全的reg文件(命令行:按TAB键自动把sys补全为system,再按一次就变为system32)&nbsp;</p><p>regshell 命令行下的注册表编辑器&nbsp;</p><p>nscopy 备份员工具(当你是Backup Operators组的用户时有时你的权限会比admin还大)&nbsp;</p><p>session.rar 有了win/nt2000目标主机的密码散列值,就可以直接发送散列值给主机而登录主机 *&nbsp;</p><p>klogger.exe 一个几kb的击键记录工具,运行后会在当前目录生成KLOGGER.TXT文件 *&nbsp;</p><p>smb2 发动smb的中间人MITM攻击的工具，在session中插入自己的执行命令 *&nbsp;</p><p>xptsc.rar winxp的远程终端客户端(支持win2000/xp)&nbsp;</p><p>SQLhack.zip 相当快的mssql密码暴力破解器&nbsp;</p><p>mssql 相当快的mssql密码暴力破解器&nbsp;</p><p>ntcrack.zip 利用获取到的MD4 passwd hash破解帐号密码&nbsp;</p><p>SQLSniffer.rar MSsql的密码明文嗅探器&nbsp;</p><p>TelnetHack.rar 在拥有管理员权限的条件下，远程打开WIN2000机器的Telnet服务&nbsp;</p><p>RFPortXP.exe XP下关联端口与进程的程序&nbsp;</p><p>SQLTools.rar mssql工具包&nbsp;</p><p>ServiceApp.exe 远程安装/删除服务&nbsp;</p><p>hgod 具有SYN/DrDos/UDP/ICMP/IGMP拒绝服务测试功能的选项&nbsp;</p><p>hscan 小型综合扫描器(支持cisco,mysql,mssql,cgi,rpc,ipc(sid),ftp,ssh,smtp等等相当全面)&nbsp;</p><p>HDoor.rar ping后门(icmp后门)&nbsp;</p><p>SIDUserEnum.exe 利用sid得到用户列表(小榕的那个sid有时不能完全列举出来) *&nbsp;</p><p>RPC_LE.exe 利用rpc溢出使win2k重启(对sp3+sp4hotfix有效) *&nbsp;</p><p>r3389.exe 查询Terminal Server更改后的端口（1秒内） *&nbsp;</p><p>smbsniffer.exe 获取访问本地主机网页的主机散列值(支持截获内网主机散列) *&nbsp;</p><p>NetEnum.exe 通过3389端口+空连接获取对方主机大量信息 *&nbsp;</p><p>aspcode.exe 经测试最有效的asp溢出程序第二版(对sp2有效)&nbsp;</p><p>sslproxy 针对使用ssl加密协议的代理（扫描器通过它就可以扫描ssl主机了!!!!) *&nbsp;</p><p>lsa2 在lsa注册表键里获取winnt/2k的明文密码包括sqlserver的(打了补丁就没用了) *&nbsp;</p><p>psu.exe 用指定进程的权限打开指定的程序&nbsp;</p><p>ldap.msi ldap 轻量级目录服务客户端,通过389端口获取主机大量信息如账号列表 *&nbsp;</p><p>rootkit 从系统底层完美隐藏指定进程，服务，注册表鍵并可以端口绑定的内核级win2k后门!!! *&nbsp;</p><p>后记:&nbsp;</p><p>在我做安全检测和渗透入侵的时候，这些工具都帮了我不小的忙(当然还有一些大工具如ISS、SSS、X-SCAN)。当然，有时候扫描不出漏洞时就要靠自己去分析安全隐患了，这样的例子不少，比如我对一些网站成功地渗透入侵的事例其中就是利用了大量的脚本和sql知识（只能利用80端口并且xp_cmdshell等几十个扩展存储都不可恢复）以及对安全模型的理解，而工具派不上任何用场。所以我有一条安全检测准则：%10的工具灵活应用+%30经验技术+%60的分析=一次较有深度的安全检测.https://feilongwl.cn/Public/Uploads/2017-02-03/589486ee73914.jpg</p>', 'https://feilongwl.cn/Public/Uploads/2017-02-03/589486ee73914.jpg', '1', '27', '1498031502', '1498031502', '1582', '0', '', '0', '0', '', '', '', '1');
INSERT INTO `blog_article` VALUES ('294', '给大家介绍下国内最顶尖的用到的黑客工具', '<p><span style=\"color: rgb(0, 0, 0); font-size: 14px;\">扫描检测&nbsp;</span></p><p>X-scan 安全焦点出品的国内很优秀的扫描工具，采用多线程方式对指定IP地址段(或单机)进行安全漏洞检测，支持插件功能，提供了图形界面和命令行两种操作方式。 &nbsp;</p><p>流光 国人的骄傲，由高级程序员小榕编写的一款强悍的扫描器。大家都知道。就不介绍了。 &nbsp;</p><p>X-way 一款优秀功能多线程扫描工具。也都应该用过。不作介绍了。 &nbsp;</p><p>Nmap 这个就厉害了,安全界人人皆知的非常有名气的一个扫描器!作者Fyodor. &nbsp;</p><p>Domain 集WHOIS查询、上传页面批量检测、木马上传、数据库浏览及加密解密于一体. &nbsp;</p><p>SuperScan 强大的TCP端口扫描器、Ping和域名解析器! &nbsp;</p><p>Hscan 这是款运行在WinNT/2000下的漏洞扫描工具，有GUI以及命令行两种扫描方式! &nbsp;</p><p>WIN2K自动攻击探测机 WinNT/2000自动攻击探测机。&nbsp;</p><p>4899空口令探测 能够快速的扫描到被安装了radmin服务端4899端口的空口令IP! &nbsp;</p><p>SHED 一个用来扫描共享漏洞的机器的工具! &nbsp;</p><p>Hscan 这是款运行在Win NT/2000下的漏洞扫描工具，有GUI以及命令行两种扫描方式! &nbsp;</p><p>Blue\'s port scan 一款绿色的扫描软件，速度很快。 &nbsp;</p><p>WebDAVScan 针对WEBDAV漏洞的扫描工具! &nbsp;</p><p>远程监控 &nbsp;</p><p>冰河 国内最有名,历史最悠久的木马冰河!本版本是冰河的最新版本,服务器端只有16KB。 &nbsp;</p><p>灰鸽子 灰鸽子工作室-葛军同志的作品!偶最喜欢的一款木马。 &nbsp;</p><p>黑洞 藏鲸阁-陈经韬编写的著名远程控制程序!也是国内比较优秀的一款木马。 &nbsp;</p><p>网络神偷 网络神偷是一个专业级的远程文件访问工具!具有反弹功能! &nbsp;</p><p>Radmin3.2影子版 非常有名的监视程序!并非木马,所以服务端不会被查杀!（现在部分杀毒查杀） &nbsp;</p><p>脚本注入 &nbsp;</p><p>NBIS2 商业破解版 NBIS2 商业完美破解911群专用版！注册码：1111-1111-1111-1111 &nbsp;</p><p>CASI 1.10 安全天使-Superhei编写的一个php注射工具，亦是国内首发的第一个php注射工具! &nbsp;</p><p>啊D之SQL注入工具 啊D编写的一个SQL注入工具``扫描及猜解速度绝对一流!且操作简单，容易上手！ &nbsp;</p><p>小幽狂注幽灵 网上新出现的注入工具``功能亦相当强大``小幽制作! &nbsp;</p><p>入侵必备 &nbsp;</p><p>SQL综合利用工具 非常好的一个SQL连接器,除了可以输入CMD命令外,还可以直接上传软件! &nbsp;</p><p>SuperSQLEXEC 用来连接sql server的工具！ &nbsp;</p><p>3389.exe 开远程机器3389端口的小东东!只要把程序上传到肉鸡运行后,重启既可! &nbsp;</p><p>c3389.exe 是一个可以显示、更改本机或远程主机终端服务端口的小程序! &nbsp;</p><p>3389.bat 一个开3389端口的批量处理!&nbsp;</p><p>3399终端登陆器 用来远程登陆3389肉鸡终端的工具!这个win2000以上都有,以下的都没有! &nbsp;</p><p>Opentelnet 远程开telnet的工具! &nbsp;</p><p>NTLM.exe 去除ntlm验证的小工具,上传后执行,然后再telnet上去既可! &nbsp;</p><p>Serv-u.exe Serv-u专用提权程序! &nbsp;</p><p>Hide Admin V2.0 用来隐藏肉鸡上管理员帐号的工具!不过管理员帐号必须有$号哦! &nbsp;</p><p>3389终端复制补丁 只要安装了该补丁,就可以直接把你需要上传的东西拖拽到肉鸡上!非常方便哦!&nbsp;</p><p>TFTP32 非常使用的一个上传工具！也是大家经常使用的哦！ &nbsp;</p><p>Wget.exe 命令行下的http下载软件! &nbsp;</p><p>Pulist.exe 使用pulist.exe 来获取已经登陆帐户的winlogon.exe 的PID 值! &nbsp;</p><p>FindPass.exe 找管理员密码，需要PULIST配合! &nbsp;</p><p>入侵助手1.0 该工具可以将dos下的入侵命令直接生成给黑客! &nbsp;</p><p>Snake的代理跳板 让机器成为sock5代理软件的程序,可以用它隐藏自己的ip &nbsp;</p><p>Fport.exe 命令行下查看系统进程与端口关联!&nbsp;</p><p>IEcookiesView COOKIES欺骗、修改工具!在得到MD5密码后,利用该工具做coolies欺骗最好不过 &nbsp;</p><p>nc.exe NC.EXE是一个非标准的telnet客户端程序！安全界有名的军刀! &nbsp;</p><p>WinSock Expert汉化版 有名的抓包工具!WinSock Expert v0.6 beta1草哲汉化版 &nbsp;</p><p>后门工具 &nbsp;</p><p>WinShell v5.0 孤独剑客写的一个后门工具``很实用的哦`现在还是最新版的5.0 &nbsp;</p><p>Ntrootkit 从系统底层完美隐藏指定进程,服务,注册表键并可以端口绑定的内核级Win2k后门! &nbsp;</p><p>CleanIISLog IIS 小榕编写的一个iis日志清除工具! &nbsp;</p><p>elsave.exe 小榕编写的日志清除工具! &nbsp;</p><p>wollf.exe 扩展Telnet服务，集成Ftp服务器、键盘记录、端口转发等功能，可反向连接等! &nbsp;</p><p>ca.exe 小榕编写的一个远程克隆账号工具!&nbsp;</p><p>cca.exe 检查是否有克隆账号,同样是小榕编写的! &nbsp;</p><p>srv.exe 孤独剑客写的一个后门工具``很实用的哦`现在防杀`` &nbsp;</p><p>cmdbind cmdbind利用远程线程和管道在WINLOGON.EXE和SPOOLSV.EXE中建立远程线.... &nbsp;</p><p>pk.exe 这是一个杀进程的小工具``挺实用,我多大时候是用来杀对方机器上的防火墙 &nbsp;</p><p>ackcmd.exe 一个ICMP通道的后门工具，能够穿越某些规则配置的防火墙!&nbsp;</p><p>IP发送者 只要在肉鸡上安装了该服务端,每当肉鸡重启时,都会把IP发送到你的邮箱里去!&nbsp;</p><p>黑客之门 hdoor 1.0!黑客之门(hacker\'s door),新出的一个非常先进的后门工具! &nbsp;</p><p>ASP站长助手6.0更正版 ASP站长助手6.0更正版!ASP站长助手6.0最新版!桂林老兵制作! &nbsp;</p><p>海阳顶端ASP木马2006 海阳顶端网ASP木马2006官方正式版! &nbsp;</p><p>冰狐浪子asp木马 非常小型的asp木马,功能也很多!&nbsp;</p><p>密码工具 &nbsp;</p><p>啊拉QQ大盗 一款盗QQ的软件，最新版支持FTP接收 &nbsp;</p><p>黑雨-邮箱密码破解器 破解POP3邮箱密码的工具,支持多线程`` &nbsp;</p><p>MD5解密器速度加强版 这个版本为改进版,破解MD5加密数据快得惊人,已测试过!厉害`` &nbsp;</p><p>L0phtCrack.v5.04 非常强悍的一个破解工具``强烈推荐`&nbsp;</p><p>多功能密码破解器 功能非常强大的密码破解工具,几乎什么密码都能破解!&nbsp;</p><p>网吧工具 &nbsp;</p><p>还原转存大师 藏鲸阁出的还原转存大师,大家都认识!不做介绍! &nbsp;</p><p>还原精灵密码读取 还原精灵密码读取!读取还原精灵密码的工具! &nbsp;</p><p>还原卡密码破解程序 非常好用的还原卡密码破解程序! &nbsp;</p><p>Pubwin4.3 修改程序 目的:跳过管理验证,并且可以免费上网 &nbsp;</p><p>美萍9.0密码破解器1.0 美萍9.0密码破解器1.0!做破解使用! &nbsp;</p><p>网吧管理集成破解器 网吧管理集成破解器,功能挺多的哦! &nbsp;</p><p>Bios密码探测器 Bios密码探测器,速度很快的哦! &nbsp;</p><p>共享密码扫描器 共享密码扫描器,也是一个不错的工具! &nbsp;</p><p>注册表解锁器 注册表破解器!解锁用的! &nbsp;</p><p>网上邻居密码破解器 网上邻居密码破解器,速度也很快哦! &nbsp;</p><p>综合工具 &nbsp;</p><p>UltraEdit V10.0中文版 一款极棒的文字、Hex、ASCII 码编辑工具!&nbsp;</p><p>WinHex 11.2 汉化版 一个很不错的16进制文件编辑与磁盘编辑软件! &nbsp;</p><p>OllyDbg-v1.10 动态调试工具,用于反汇编!&nbsp;</p><p>W32Dasm 10.0 汉化版 静态调试工具,用于反汇编! &nbsp;</p><p>S-Demo2.0破解版 现在很多的黑客动画教程几乎都是用该工具录制的! &nbsp;</p><p>屏幕录象专家破解版 同样是一款录象教程制作软件，用得也很广泛。 &nbsp;</p><p>辅臣数据库浏览器 很优秀的一款数据库浏览软件 &nbsp;</p><p>&nbsp;</p>', 'https://feilongwl.cn/Public/Uploads/2017-02-03/5894870a5838b.png', '1', '27', '1498031543', '1498031543', '1553', '0', '', '0', '0', '', '', '', '1');
INSERT INTO `blog_article` VALUES ('295', '利用FD撸东西的人必看！', '<p>在这里我劝你们网络小白不要碰fd，如果实在喜欢fd我也无所谓的啦~不要存在着，你撸一点不会被抓这样的心理。</p><p>你只要撸了别人就会有记录，别人照样可以告你的。 话多了点给网络小白看看撸fd的后果</p><p>撸的手机这些虽然订单是几毛但到货之后需要交原价几千的</p><p>撸少了就烧香拜佛 撸多了必死 就算你几毛撸100话费 你一个就撸了100 那么其他人呢？</p><p>加起来撸了别人几万，几万损失，商家收不到钱，你当别人傻子，就算那些给你0元发货了，到货签收也是0元。</p><p>就算你聪明写你家附近，你电话咋办呢，电话卡是实名的。一样可以追回。</p><p>且行且珍惜吧，别再听信那些什么fd收徒的，明摆是在害你，也是在坑你钱，要那么吃香他还收徒个屁啊。</p><p>好多撸Fd撸多的都已经被抓了，相信你们都知道身边的一两个还在想学，还在去拜师的那就是傻逼了。</p><p>如果你觉得我提醒没啥用，存在侥幸心里的，我也没什么办法，我只是温馨提醒你们喜欢fd的人。</p>', 'https://feilongwl.cn/Public/Uploads/2017-02-03/589487fce8587.jpg', '1', '34', '1498031572', '1498031572', '3045', '0', '', '0', '0', '', '', '', '1');
INSERT INTO `blog_article` VALUES ('296', 'Android渗透测试工具大合集', '<p><span style=\"font-size: inherit;\"><span style=\"font-size: inherit; color: rgb(68, 68, 68);\">前话</span></span></p><p>当我们连入一个莫名的WIFI，除了上网，还能干些什么？</p><p>当然是渗透！已不至于只能上网</p><p>Android传承着Linux的血统，无疑使 渗透 从机器端到各种终端，使用起来更加方便，工具集中了众多方法，大大提高了渗透的效率（当然 不推荐傻瓜式工具，这里只是入门，高手勿喷，初学者了解）</p><p>大名鼎鼎的dsploit</p><p><img src=\"http://p2.pstatp.com/large/52d00024a20a7c5860a\" alt=\"Android渗透测试工具大合集\"></p><p>地址:&nbsp;<a href=\"http://dsploit.net/\">http://dsploit.net/</a></p><p>演示视频:<a href=\"http://www.dsploit.net/video/\">http://www.dsploit.net/video/</a></p><p>下载:&nbsp;<a href=\"http://www.dsploit.net/download/\">http://www.dsploit.net/download/</a></p><p>满足条件: Android2.3+,root，busybox</p><p>dsploit作为一款优秀的渗透工具，几乎无人不知无人不晓，其功能之强大，功能包括</p><p>端口扫描</p><p>漏洞发现</p><p>对路由器扫描</p><p>伪造数据包</p><p>会话控制(需要MSF RPC 连接)</p><p>中间人攻击</p><p>密码破解</p><p>有能力可以攻占路由器( 没成功 )</p><p>其中 中间人攻击中 可以自定义JS脚本（构造XSS）</p><p><img src=\"http://p2.pstatp.com/large/52e00024a6f55fb1a65\" alt=\"Android渗透测试工具大合集\"></p><p><img src=\"http://p3.pstatp.com/large/52d00024a2111a1af55\" alt=\"Android渗透测试工具大合集\"></p><p><img src=\"http://p3.pstatp.com/large/52e00024a6e1bf91362\" alt=\"Android渗透测试工具大合集\"></p><p>而具体的内容Google 一搜一麻袋，不再多说，</p><p>该项目还在不断更新.</p><p>更加强大的Network Spoofer</p><p><img src=\"http://p5.pstatp.com/large/50100096039fd4f145e\" alt=\"Android渗透测试工具大合集\"></p><p>地址:&nbsp;<a href=\"http://www.digitalsquid.co.uk/netspoof/\">http://www.digitalsquid.co.uk/netspoof/</a></p><p>下载:&nbsp;<a href=\"https://s3.amazonaws.com/\">https://s3.amazonaws.com/</a></p><p>演示视频:&nbsp;<a href=\"https://www.youtube.com/watch?v=sm-llBJA8EA\">https://www.youtube.com/watch?v=sm-llBJA8EA</a></p><p>满足条件: Android2.3+,root，busybox</p><p><img src=\"http://p1.pstatp.com/large/53000024bb78881ff66\" alt=\"Android渗透测试工具大合集\"></p><p><img src=\"http://p2.pstatp.com/large/53000024bb8d9cfd5cf\" alt=\"Android渗透测试工具大合集\"></p><p>只知dsploit 而不解Network Spoofer，其功能之强大远比dsploit</p><p>其具有</p><p>“多项欺骗”（multiple spoofs)</p><p>Blue ball machine! (按照说明 redirect all sites to the blue ball machine 没试过，呵呵）</p><p>重定向YouTube</p><p>delete random words (删除任意文字)</p><p>替换Google 搜素</p><p>包含dsploit 功能</p><p>更加侧重于渗透而非破解,强烈推荐！</p><p>超炫的zANTI</p><p><img src=\"http://p3.pstatp.com/large/52c000249c3bcee18bc\" alt=\"Android渗透测试工具大合集\"></p><p>地址:&nbsp;<a href=\"https://www.zimperium.com/zanti-mobile-penetration-testing\">https://www.zimperium.com/zanti-mobile-penetration-testing</a></p><p>免费版下载:&nbsp;<a href=\"https://www.zimperium.com/zanti-download\">https://www.zimperium.com/zanti-download</a></p><p>满足条件: Android2.3+,root，busybox</p><p><img src=\"http://p3.pstatp.com/large/53000024bb9fbdae701\" alt=\"Android渗透测试工具大合集\"></p><p>\"zANTI is a comprehensive network diagnostics toolkit that enables complex audits and penetration tests at the push of a button. It provides cloud-based reporting that walks you through simple guidelines to ensure network safety.\"</p><p>个人认为翻译成 “三体”更加合适，因为这更像一个安全体系，分成三个部分 ，ANTI,IPS,CONSOLE</p><p>详看截图.</p><p><img src=\"http://p3.pstatp.com/large/52e00024a70be91a1e2\" alt=\"Android渗透测试工具大合集\"></p><p><img src=\"http://p2.pstatp.com/large/52f000249b24247d16a\" alt=\"Android渗透测试工具大合集\"></p><p><img src=\"http://p3.pstatp.com/large/52f000249b39f644dfc\" alt=\"Android渗透测试工具大合集\"></p><p>功能特性</p><p>网络诊断，复杂的审计和渗透测试</p><p>中间人攻击和包探嗅</p><p>非常有好的界面</p><p>namap端口扫描，探测出操作系统</p><p>密码分析</p><p>分为免费版和付费版，免费版对于连接服务器和自定义js和图片有限制，但初学者已经完全够用，</p><p>比起dsploit和Network Spoofs来更加专业，界面甩十条大街.</p><p>小巧的DroidSheep</p><p><img src=\"http://p1.pstatp.com/large/52c000249c47247be6d\" alt=\"Android渗透测试工具大合集\"></p><p>地址:&nbsp;<a href=\"http://droidsheep.de/\">http://droidsheep.de/</a></p><p>下载:&nbsp;<a href=\"http://droidsheep.de/?page_id=23\">http://droidsheep.de/?page_id=23</a></p><p>代码:&nbsp;<a href=\"https://code.google.com/p/droidsheep/\">https://code.google.com/p/droidsheep/</a></p><p>演示视频:&nbsp;<a href=\"https://www.youtube.com/watch?v=z7NUluxUORs\">https://www.youtube.com/watch?v=z7NUluxUORs</a></p><p>满足条件: Android2.3+,root，busybox</p><p><img src=\"http://p1.pstatp.com/large/52c000249c59d1536d6\" alt=\"Android渗透测试工具大合集\"></p><p>DriodSheep</p><p>捕获facebook、twitter、linkedin和其他账户。</p>', 'https://feilongwl.cn/Public/Uploads/2017-02-03/58948bd31cefc.jpg', '1', '3', '1498031579', '1498031579', '1209', '0', '', '0', '0', '', '', '', '1');
INSERT INTO `blog_article` VALUES ('297', 'New1.5御剑开源', '<p><span style=\"font-size: 13px;\">New御剑1.5后台扫描工具（加强字典版）&nbsp;t00ls大神的作品,方便快速查找网站用户后台登陆地址，同时也为程序开发人员增加了难度，尽量独特的后台目录结构。</span><br><span style=\"font-size: 13px;\">很强大的加强字典。</span><br><span style=\"font-size: 13px;\">好东西不解释，想下的话就下吧…</span></p><p><span style=\"color: rgb(54, 54, 54); font-size: small;\"><span style=\"color: rgb(255, 0, 0);\">这个貌似是御剑内部版的，，还有论坛登录验证，不过被我去掉了</span></span><span style=\"color: rgb(54, 54, 54); font-size: 14px;\">.</span></p><p><img src=\"http://bbs.itxueke.com/data/attachment/forum/201607/08/172121ctvtbbzf2avos24s.png.thumb.jpg\" alt=\"\"></p><table><colgroup><col width=\"NaN%\"><col width=\"NaN%\"></colgroup><thead><tr><th style=\"text-align: left;\">123</th><th style=\"text-align: left;\"><code class=\"java plain\">FrmMain.Show() \'直接载入主窗口</code><code class=\"java plain\">Me.Hide()</code><code class=\"java plain\">Exit Sub \'退出</code></th></tr></thead></table><p><img src=\"http://www.test404.com/xz.jpg\" alt=\"\"></img></p>', 'https://feilongwl.cn/Public/Uploads/2017-02-03/58948b630c481.jpg', '1', '3', '1498031627', '1498031627', '1219', '0', '', '0', '0', '', '', '', '1');
INSERT INTO `blog_article` VALUES ('298', '原创入侵网吧主机的思路装逼说说', '<p>装逼思路：<span style=\"color: rgb(166, 166, 166); font-size: 14px;\">&nbsp;</span></p><pre><code><div style=\"margin: 0px 0px 15px; word-wrap: break-word;\"><span style=\"color: rgb(36, 64, 97); font-size: 18px;\"><strong><span style=\"background-color: rgb(255, 255, 255);\">简单的总结一下入侵网吧主机的思路，前几天去网吧通宵，就帮网吧安全检测，桌面有一个留言板，先找后台，试弱口令，百度找找网站源码，先试下默认的不行再看看数据库路径，解密账号密码，登陆之后用asp或php的对应一句话修改，然后菜刀连接，拿到shell再提权，后面就不多说了。。。</span><img src=\"http://cnc.qzonestyle.gtimg.cn/qzone/em/e122.gif\" style=\"cursor: pointer; margin: 0px 5px; max-height: 24px;\"></strong></span></div><div><span style=\"color: rgb(36, 64, 97); font-size: 18px;\"><strong><br></strong></span></div></code></pre>', 'https://feilongwl.cn/Public/Uploads/2017-02-03/58948915300f4.jpg', '1', '3', '1498031798', '1498031798', '1077', '0', '', '0', '0', '', '', '', '1');
INSERT INTO `blog_article` VALUES ('299', 'Hack神器-中国菜刀-(shell管理)', '<p>中国菜刀，不是原来切菜做饭的道具，而是一款专业的网站管理软件，用途广泛，使用方便，小巧实用。<br>只要支持动态脚本的网站，都可以用中国菜刀来进行管理！在非简体中文环境下使用，<br>自动切换到英文界面。UINCODE方式编译，支持多国语言输入显示。</p><p>&nbsp;&nbsp;<img alt=\"Hack神器-中国菜刀-(shell管理)\" src=\"http://www.exehack.net/wp-content/uploads/2013/12/zgcd1-300x185.jpg\" width=\"400\" height=\"248\"></p><p><img alt=\"Hack神器-中国菜刀-(shell管理)\" src=\"http://www.exehack.net/wp-content/uploads/2013/12/zgcd2-300x183.jpg\" width=\"400\" height=\"244\"></p><h2>功能介绍:<br></h2><p>只要网页是非静态页面:也就是支持动态脚本的网站 （asp,jsp,aspx,php），都可以用中国菜刀来进行管理！<br>主要功能有：文件管理，虚拟终端，数据库管理。<br>UINCODE方式编译，支持多国语言输入显示。&nbsp;<strong>一、EVAL客户端部分</strong>&nbsp;1.服务端只需要简单的一行代码，即可用此程序实现常用的管理功能。<br>支持的服务端脚本：PHP, ASP，NET。<br>在服务端运行的代码如下：&nbsp;</p><p>PHP:</p><table><colgroup><col width=\"NaN%\"><col width=\"NaN%\"></colgroup><thead><tr><th style=\"text-align: left;\">1</th><th style=\"text-align: left;\"><span style=\"color: rgb(255, 0, 0);\"><span style=\"color: rgb(128, 0, 128);\">eval</span><span style=\"color: rgb(51, 51, 51);\">(</span><span style=\"color: rgb(0, 45, 122);\">$_POST</span><span style=\"color: rgb(51, 51, 51);\">[</span><span style=\"color: rgb(0, 0, 0);\">w</span><span style=\"color: rgb(51, 51, 51);\">]</span><span style=\"color: rgb(51, 51, 51);\">)</span><span style=\"color: rgb(51, 51, 51);\">;</span>?&gt;</span></th></tr></thead></table><p>ASP:</p><table><colgroup><col width=\"NaN%\"><col width=\"NaN%\"></colgroup><thead><tr><th style=\"text-align: left;\">1</th><th style=\"text-align: left;\"><span style=\"color: rgb(255, 0, 0);\">&lt;%</span><span style=\"color: rgb(0, 0, 0);\">eval</span><span style=\"color: rgb(0, 111, 224);\">&nbsp;</span><span style=\"color: rgb(0, 0, 0);\">request</span>(<span style=\"color: rgb(0, 0, 0);\">\"pass\"</span>)<span style=\"color: rgb(255, 0, 0);\">%&gt;</span></th></tr></thead></table><p>&nbsp;.NET:</p><table><colgroup><col width=\"NaN%\"><col width=\"NaN%\"></colgroup><thead><tr><th style=\"text-align: left;\">1</th><th style=\"text-align: left;\"><span style=\"color: rgb(255, 0, 0);\">&lt;%</span>@<span style=\"color: rgb(0, 111, 224);\">&nbsp;</span><span style=\"color: rgb(0, 0, 0);\">Page</span><span style=\"color: rgb(0, 111, 224);\">&nbsp;</span><span style=\"color: rgb(0, 45, 122);\">Language</span><span style=\"color: rgb(255, 0, 0);\">=</span><span style=\"color: rgb(0, 0, 0);\">\"Jscript\"</span><span style=\"color: rgb(255, 0, 0);\">%&gt;</span><span style=\"color: rgb(255, 0, 0);\">&lt;%</span><span style=\"color: rgb(0, 0, 0);\">eval</span>(<span style=\"color: rgb(0, 45, 122);\">Request</span>.<span style=\"color: rgb(0, 45, 122);\">Item</span>[<span style=\"color: rgb(0, 0, 0);\">\"pass\"</span>],<span style=\"color: rgb(0, 0, 0);\">\"unsafe\"</span>);<span style=\"color: rgb(255, 0, 0);\">%&gt;</span></th></tr></thead></table><p>&nbsp;(注意: .NET要单独一个文件或此文件也是Jscript语言)</p><p>2.使用方法:</p><p>在主视图中右键/添加，在弹出的对话框中输入服务端地址，连接的密码(请注意上例中的pass字串)，选择正确的脚本类型和语言编码，保存后即</p><p>使用文件管理，虚拟终端，数据库管理三大块功能。要是其它都没错误，那么可能就是你把语言编码选错了。</p><p>1.<strong>文件管理</strong>：[特色]缓存下载目录，并支持离线查看缓存目录;</p><p>2.<strong>虚拟终端</strong>：[特色]人性化的设计，操作方便;(输入HELP查看更多用法)</p><p>3.<strong>数据库管理</strong>：[特色]图形界面,支持MYSQL,MSSQL,ORACLE,INFOMIX,ACCESS</p><p>以入支持ADO方式连接的数据库。</p><p><img alt=\"Hack神器-中国菜刀-(shell管理)\" src=\"http://www.xiaozhe520.com/xz.jpg\"></img></p>', 'https://feilongwl.cn/Public/Uploads/2017-02-03/58948722af23e.jpg', '1', '27', '1498031870', '1498031870', '2340', '0', '', '0', '0', '', '', '', '1');
INSERT INTO `blog_article` VALUES ('300', '最新 burpsuite 破解版', '<p>Burp Suite是一个Web应用程序集成攻击平台，它包含了一系列burp工具，这些工具之间有大量接口可以互相通信，这样设计的目的是为了促进和提高整个攻击的效率。平台中所有工具共享同一robust框架，以便统一处理HTTP请求，持久性，认证，上游代理，日志记录，报警和可扩展性。&nbsp; BurpSuite允许攻击者结合手工和自动技术去枚举、分析、攻击Web应用程序。这些不同的burp工具通过协同工作，有效的分享信息，支持以某种工具中的信息为基础供另一种工具使用的方式发起攻击。</p><p>&nbsp;这个需要java环境 这个必须的</p><p>jre6下载地址：<a href=\"http://pan.baidu.com/s/1i3zMpQd\">http://pan.baidu.com/s/1i3zMpQd</a></p><p>安装一直下一步就行了。</p><p><span style=\"color: rgb(51, 127, 229);\">burpsuite_pro_v1.5.11 破解版</span></p><p>下载地址：<a href=\"http://pan.baidu.com/s/1pJwSk47\">http://pan.baidu.com/s/1pJwSk47</a></p><p><span style=\"color: rgb(229, 51, 51);\">burpsuite_pro_v1.5.18 破解版</span></p><p>下载地址：<a href=\"http://pan.baidu.com/s/1kTDpxgr\">http://pan.baidu.com/s/1kTDpxgr</a></p>', 'https://feilongwl.cn/Public/Uploads/2017-02-03/589487313ab06.png', '1', '27', '1498031894', '1498031894', '1501', '0', '', '0', '0', '', '', '', '1');
INSERT INTO `blog_article` VALUES ('301', '语音详讲玩转VR', '<p><img src=\"http://feilongwl.cn/Public/umeditor/php/upload/20160521/14638194873598.png\"></p><p>某宝买来的资源分享给大家：</p><p>[日本][160510][360全景]VR福利资源（上）</p><p>链接:&nbsp;<a href=\"http://pan.baidu.com/s/1pL07KWN\">http://pan.baidu.com/s/1pL07KWN</a>&nbsp;密码: nmma</p><p>[160505][日本]VR福利资源</p><p>链接:&nbsp;<a href=\"http://pan.baidu.com/s/1slBYZOp\">http://pan.baidu.com/s/1slBYZOp</a>&nbsp;密码: y62a</p><p>[日本][160503]VR福利资源（补档）</p><p>链接:&nbsp;<a href=\"http://pan.baidu.com/s/1slrGprf\">http://pan.baidu.com/s/1slrGprf</a>&nbsp;密码: nwr7</p><p>vr精品资源：</p><p>链接:&nbsp;<a href=\"http://pan.baidu.com/s/1c2sgI0S\">http://pan.baidu.com/s/1c2sgI0S</a>&nbsp;密码: u2my</p><p>终极福利 老司机专属：</p><p>链接:&nbsp;<a href=\"http://pan.baidu.com/s/1gfqEGKz\">http://pan.baidu.com/s/1gfqEGKz</a>&nbsp;密码: iiww</p><h2><strong>解压密码 &nbsp;&nbsp;</strong><span style=\"color: rgb(79, 97, 40);\">zuolengchan123</span></h2><h1>原版语音教程下载地址：<strong><a href=\"http://pan.baidu.com/s/1hs4PMkO\" target=\"_blank\">http://pan.baidu.com/s/1hs4PMkO</a></strong></h1><h3>迅雷播放种子的方法</h3><p>迅雷下载<br>1、电脑下载迅雷7 直接把下载好的种子拉进去 点击立即下载即可， 2、手机下载一个迅雷，在“我的”里面打开下载管理，点击+号<br>选择新建bt任务，点击下载——就可以了&nbsp;<br>视频导入手机<br>苹果手机的下载itools——数据线连接电脑——点击视频——点击导入——选择文件，就可以了<br>安卓的电脑下载360助手——数据线连接——直接选择就可以导入 大家别忘记了QQ还有传文件的功能，在电脑用QQ就可以传到手机上</p>', 'https://feilongwl.cn/Public/Uploads/2017-02-03/5894874013a0d.png', '1', '3', '1498031916', '1498031916', '1355', '0', '', '0', '0', '', '', '', '1');
