INSERT INTO `blog_article` VALUES ('342', '2017.7.26近期软件汇总', '<p>QQ刷步数 配合活动撸QB红包破零</p><p>视频段子提取工具</p><p>QQ动态恶搞头像上传&nbsp;</p><h1><span style=\"color: rgb(128, 128, 128); font-size: 14px;\">软件下载地址：</span><a href=\"http://pan.lanzou.com/u/feilong520\" target=\"_blank\">http://pan.lanzou.com/u/feilong520</a><span style=\"color: rgb(128, 128, 128); font-size: 14px;\">&nbsp;</span></h1>', 'https://feilongwl.cn/Public/Uploads/2017-07-26/597814eb6bbab.png', '1', '25', '1501041936', '1529117004', '2431', '0', '', '0', '0', '', '', '', '1');
INSERT INTO `blog_article` VALUES ('344', '27部黑客电影送给你们', '<p><span style=\"color: rgb(0, 176, 80);\">在多数人眼中，黑客通常是一群无聊至极没有什么趣味的人，在他们的世界里仿佛只有计算机和那敲不完的代码。但事实真的如此吗？让我们回味一下看《黑客帝国》、《幽灵》等黑客题材电影时的场景。有木有种热血澎湃，瞬间变成小迷妹的冲动？其实在现实生活中，他们也有许多乐趣和鲜为人知的经历和故事。下面，是为大家精心整理的27部黑客题材纪录片，现在让我们一起走近他们的世界。</span></p><h3>1. 微软英雄（<a href=\"http://www.imdb.com/title/tt0168122/\">Pirates of Silicon Valley</a>）</h3><p><img width=\"350\" alt=\"MV5BNDc2NTE0NzE4N15BMl5BanBnXkFtZTgwMDQ5MzgwMzE@._V1_.jpg\" src=\"http://image.3001.net/images/20170617/14976751182752.jpg!small\"></p><p>上映时间：1999年</p><p>这是一部有点幽默气息的传记电影。主要讲述了两位互联网大佬比尔盖茨和乔布斯在大学时期的斗争，以及他们为建立微软和苹果这样的全球性企业帝国，而实施的策略和行动。总的来说，这是一部讲述比尔·盖茨和史蒂夫·乔布斯兴起和冲突故事的纪录片。（不过从技术上讲这应该是部纪实片，而不是纪录片）</p><h3>2. 自由宕机时间（<a href=\"http://www.imdb.com/title/tt0309614/\">Freedom Downtime</a>）</h3><p><img width=\"323\" alt=\"MV5BMTU4MTM4NDc4NV5BMl5BanBnXkFtZTYwNjgyMDg5._V1_.jpg\" src=\"http://image.3001.net/images/20170617/14976751369445.jpg!small\"></p><p>上映时间：2001年</p><p>这是部由电影人制作的黑客纪录片。记录了美国著名骇客凯文等人的历史背景说明。凯文在1995年因为入侵电脑系统被FBI逮捕，但是他被逮捕之后，却一直没有审判，而且屡次被拒绝交保，就这样被监禁了四年，因此2600发起”Free Kevin”的自救行动，要求联邦政府释放凯文，不仅因为法院延宕审判，更因为凯文入侵系统之举并未造成任何重大损害，联邦政府也承认凯文个人并未因入侵系统而得到任何私利。2600认为，骇客不应因为“好奇心”而判刑，何况联邦政府的电脑系统防备不周才会被入侵，但凯文破解系统之后并未复制任何联邦政府的档案资料。</p><h3>3. 代码（<a href=\"http://www.imdb.com/title/tt0315417/\">The Code</a>）</h3><p><img width=\"350\" alt=\"20170617140142.jpg\" src=\"http://image.3001.net/images/20170617/14976793378052.jpg!small\"></p><p>上映时间：2001年</p><p>《代码》是2001年芬兰的一部关于GNU/Linux的英语纪录片，其中介绍了自由软件运动中卓有贡献的一些人物。</p><h3>4. 代号2600（<a href=\"http://www.imdb.com/title/tt1830538/\">Code 2600</a>）</h3><p><img width=\"350\" alt=\"20170617125521.jpg\" src=\"http://image.3001.net/images/20170617/14976753592808.jpg!small\"></p><p>上映时间：2012年</p><p>《CODE 2600》这一纪录片通过记述信息技术时代的大事件以及构建和操纵它的人才，深入探讨了时代进步对人类的影响，以及如何维护我们的个人隐私和安全问题等。</p><p>值得一提的是，黑客Jeff Moss在这部纪录片中本色出演，扮演了他自己。Jeff Moss被媒体誉为“全球身价最高黑客”，他除了是DEF CON和Black Hat两场全球黑客盛会的创办者外，还是美国国土安全咨询委员会顾问、ICANN（互联网名称与数字地址分配机构）首席安全官。</p><h3>5.&nbsp;操作系统革命（<a href=\"http://www.imdb.com/title/tt0308808/\">Revolution OS</a>）</h3><p><img width=\"325\" alt=\"MV5BMTgyNDU0NTIwNV5BMl5BanBnXkFtZTcwNzE4MDQyMQ@@._V1_.jpg\" src=\"http://image.3001.net/images/20170617/14976753731881.jpg!small\"></p><p>上映时间：2001年</p><p>虽然微软是世界上最大的软件公司，但并不是所有人都是他们产品的粉丝，也不是所有人都喜欢他们提供的业务方式。而对于全球使用最广泛的操作系统[[过滤window]]s，有许多专家对其有关许可证，所有权，发行和更改软件的严格政策提出了质疑。最著名的是理查德·斯托曼（Richard Stallman）的提出的反对意见，由于他的质疑最终导致了所谓的“开放源代码运动”，它的重点在于，计算机软件应该在经济和智力方面都是自由的的。最终，Stallman的崇拜者之一Linus Torvalds创建了一个被称为Linux的新操作系统，这是一种免费分发的软件，许多程序员认为它们显然优于[[过滤window]]s。《操作系统革命》追述了GNU、Linux、自由软件运动以及开放源代码运动长达二十余年的历史。</p><h3>&nbsp;6.&nbsp;黑客也是寻常人（<a href=\"http://www.imdb.com/title/tt1279942/\">Hackers Are People Too</a>）</h3><p><img width=\"324\" alt=\"MV5BMTc2OTk3MDY5NV5BMl5BanBnXkFtZTcwNzc2OTA5MQ@@._V1_.jpg\" src=\"http://image.3001.net/images/20170617/14976753875484.jpg!small\"></p><p>上映时间：2008年</p><p>黑客也要洗衣服；黑客也喜欢看电影；黑客可能就是你的邻居、你的哥哥或是你的朋友。这部纪录片打破了关于黑客刻板负面的形象，告诉我们黑客也像我们一样，深入剖析黑客的思维方式，解读什么才是黑客以及安全／黑客领域的女性角色，这部纪录片会让我们重新认识到底什么才是真正意义上的“黑客”。</p><h3>7.&nbsp;黑客军团故事（<a href=\"http://www.imdb.com/title/tt2177843/\">We Are Legion: The Story of the Hacktivists</a>）</h3><p><img width=\"350\" alt=\"20170617130601.jpg\" src=\"http://image.3001.net/images/20170617/14976759909373.jpg!small\"></p><p>上映时间：2012年</p><p>《黑客军团故事》讲述的是世上最着名的黑客集团——匿名者。《We Are Legion》组织由一群网络上的匿名者(Anonymous) 组成，成员来自网路世界的各个角落，他们在网路上以电子邮件、木马程式攻击企业、政府网站，在现实中更戴起V怪客面具发动占领华尔街、反核游行、反全球化等抗争，充满创意而活泼的文化现象不仅表现出民众对抗企业、政府的怒火，更将网路世代的公民意见化为实际的行动参与。</p><h3>8. KGB，计算机和我（<a href=\"http://www.imdb.com/title/tt0308449/\">The KGB, the Computer and Me</a>）</h3><p><img width=\"350\" alt=\"20170617135908.jpg\" src=\"http://image.3001.net/images/20170617/14976791872579.jpg!small\"></p><p>上映时间：1990年</p><p>1986年，由天文学转向计算机科学的克利福德·斯托尔（Clifford&nbsp;Stoll）刚刚在劳伦斯伯克利实验室（Lawrence&nbsp;Berkeley&nbsp;Laboratory）开始从事计算机系统工作，当时他注意到，两个印制的对机器使用者收费的会计课程单上的费用之间有75％的差距。有趣的是，他推断系统被黑客入侵了，并决心找到这名骇客。这是他通过以太网向德国汉诺威追踪KGB破解者马库斯·赫斯（Markus&nbsp;Hess）的再现。</p><h3>9.&nbsp;黑客民主（<a href=\"http://www.imdb.com/title/tt0808532/\">Hacking Democracy</a>）</h3><p><img width=\"375\" alt=\"MV5BMTU0MjkwMDI4Ml5BMl5BanBnXkFtZTgwNDg5OTgxMDI@._V1_.jpg\" src=\"http://image.3001.net/images/20170617/14976760969279.jpg!small\"></p><p>上映时间：2006年</p><p>在美国联邦国家、州、县选举中电子选票机要点数90%的投票，这项技术正在不断地被世界一些其他国家使用，其中包括加拿大、英国、欧洲和拉美国家。影片揭秘出了从得克萨斯州的垃圾箱到俄亥俄州的选票箱的煽动性证据，使得秘密被曝光。最后证明我们的选票可以被毫无痕迹地偷走。影片在这次著名的 ‘Hursti Hack’ 攻克 （Diebold 选票机和一个来自芬兰的电脑黑客之间的决斗）中达到了高潮 ，使美国的民主显得岌岌可危。</p><h3>10.&nbsp;第四公民（<a href=\"http://www.imdb.com/title/tt4044364/\">Citizenfour</a>）</h3><p><img width=\"350\" alt=\"20170617131011.jpg\" src=\"http://image.3001.net/images/20170617/14976762473701.jpg!small\"></p><p>上映时间：2014年</p><p>《第四公民》是劳拉·珀特阿斯执导，爱德华·斯诺登主演的纪录片，于2014年10月24日在美国上映。该片讲述的是斯诺登将美国国家安全局机密文件披露给英国《卫报》和美国《华盛顿邮报》等新闻媒体的过程及后续，还原“棱镜门”事件<span style=\"font-size: 12px;\">。</span></p><h3>11.&nbsp;我们窃取秘密：维基解密的故事（<a href=\"http://www.imdb.com/title/tt1824254/\">We Steal Secrets: The Story of WikiLeaks</a>）</h3><p><img width=\"350\" alt=\"20170617130941.jpg\" src=\"http://image.3001.net/images/20170617/14976762614305.jpg!small\"></p><p>上映时间：2013年</p><p>纪录片饶有兴趣地从多种层面描写了信息时代的透明度和我们对真相的永远不依不饶的探寻。影片详述了朱利安·阿桑奇(Julian Assange)维基解密网站(WikiLeaks)的诞生，这个网站助长了美国有史以来最大的安全缺口。影片描述了这一神秘网站的兴衰，其中穿插着美国陆军士兵布拉德利·曼宁(Bradley Manning)泄密事件，这个令人不安的高智商士兵从美国军事和外交服务器上下载了几十万个文档。</p><h3>12.&nbsp;现实生活中的海盗湾（<a href=\"http://www.imdb.com/title/tt2608732/\">TPB AFK: The Pirate Bay Away from Keyboard</a>）</h3><p><img width=\"350\" alt=\"20170617131227.jpg\" src=\"http://image.3001.net/images/20170617/1497676564991.jpg!small\"></p><p>上映时间：2013年</p><p>21世纪初，一个标榜着“实现真正的言论和文化传播自由”的网站横空出世。它就是日后大名鼎鼎并惹来无数争议的最大的档案分享网站海盗湾（Pirate Bay）。该网站由高特弗里德·萨特霍姆·瓦格、弗雷德里克·内伊以及彼得·桑德三个瑞典人创立，他们的精神和魄力得到来自全世界复制派（海盗党）的热烈支持，与此同时也遭到号称损失高达61亿美金的版权方的嫉恨。2008年，以好莱坞为首的巨头向海盗湾提起诉讼，三位创始人不得不“离开键盘”，与检方展开一连串的周旋。</p><p>一方以法律为手段，一方以技术为武器。这不仅是一场来自不同价值观阵营的战争……</p><h3>13. 网络战争（<a href=\"http://www.imdb.com/title/tt2390367/\">War for the Web</a>）</h3><p><img width=\"350\" alt=\"20170617131632.jpg\" src=\"http://image.3001.net/images/20170617/14976766218261.jpg!small\"></p><p>上映时间：2015年</p><p>我们真的有言论自由权、隐私权和安全权吗？作为高喊民主主义的美国，却似乎在最不应该受到威胁和干扰的“线上世界”剥夺人们所有的民主权利。许多闭门会议以及公司和政府之间，正试图通过各种谈判和手段来控制虚拟世界，影响甚至改变我们的互联网访问方式。我们发布的内容、建立的网站以及我们传送的数据都无时无刻受到了监视。现在是时候站出来了，为我们的网络权利而战斗！那么谁将赢得这场战争的最后胜利呢？该纪录片将为你深度剖析。</p><h3>14.&nbsp;极速下载的命运（<a href=\"http://www.imdb.com/title/tt2033981/\">Downloaded</a>）</h3><p><img width=\"350\" alt=\"20170617131745.jpg\" src=\"http://image.3001.net/images/20170617/1497676694527.jpg!small\"></p><p>上映时间：2013年</p><p>纪录P2P传输始祖Napster音乐分享网站的兴起与没落，导演亚历士温特藉此一窥网络科技对于音乐产业的巨大影响。虽然整个网站后台随着与唱片公司版权诉讼的争议而宣告终止，但新兴网络自由的圣战，才正要掀起一股时代的浪潮。</p><h3>15.&nbsp;干走电影（<a href=\"http://www.imdb.com/title/tt1422757/\">Steal This Film</a>）</h3><p><img width=\"350\" alt=\"20170617131845.jpg\" src=\"http://image.3001.net/images/20170617/14976767547710.jpg!small\"></p><p>上映时间：2006年</p><p>《干走电影》是一个于2006年开始的系列电影计划，电影内容是关于反抗知识产权运动的纪录片，并且以BitTorrent点对点技术协定散布电影，而不是在电影院进行公映。</p><h3>16. 深网：比特币和丝绸之路未透露的故事（<a href=\"http://www.imdb.com/title/tt3312868/\">Deep Web</a>）</h3><p><img width=\"350\" alt=\"20170617132343.jpg\" src=\"http://image.3001.net/images/20170617/14976770515341.jpg!small\"></p><p>上映时间：2015年</p><p>在《Deep Web》中，导演Alex Winter 提到了丝路的群体精神、偏自由主义的政治倾向，以及 “丝路”创始人Ross Ulbricht关于丝路使得毒品交易更安全的言论，不过，他并不想给出一个明确的结论。</p><p>Winters 说，“变化来的如此快速，如此激烈，因此，这也带来了许多的恐惧和误解，丝路落入了我们面临的最具争议的三个领域：虚拟空间、毒品战争以及一种不受监管的货币影响下的财务市场。但最终，它只是一个黑暗网络中的社群。看到它被如此对待，我的感觉是，人们构建了神话，然后，他们攻击了神话。</p><h3>17.&nbsp;国际黑客大会：纪录片（<a href=\"http://www.imdb.com/title/tt3010462/\">DEFCON: The Documentary</a>）</h3><p><img width=\"350\" alt=\"20170617132452.jpg\" src=\"http://image.3001.net/images/20170617/14976771223970.jpg!small\"></p><p>上映时间：2013年</p><p>DEFCON是在内华达州拉斯维加斯举行的世界上最大的黑客会议。2012年DEFCON举办了第二十次会议。会议对拍摄有着严格的政策，但在DEFCON 20会议期间，一位纪录片拍摄人员被获准到会议厅内对会议进行拍摄记录。该纪录片通过全面的视角，为大家详细的记录了DEF CON大会为期4天的各项会议、事件以及与会人员，并涵盖了DEF CON大会成功的历史进程和独特经验。</p><h3>18. 连线中断（<a href=\"http://www.imdb.com/title/tt2417174/\">DSKNECTD</a>）</h3><p><img width=\"350\" alt=\"20170617132604.jpg\" src=\"http://image.3001.net/images/20170617/14976771946720.jpg!small\"></p><p>上映时间：2013年</p><p>探索智能手机，社交媒体和互联网如何深刻地改变我们互相交流及体验的方式，它们的利弊又是什么？</p><h3>19. 黑客大战（<a href=\"http://www.imdb.com/title/tt4047350/\">The Hacker Wars</a>）</h3><p><img width=\"350\" alt=\"20170617132703.jpg\" src=\"http://image.3001.net/images/20170617/14976772539853.jpg!small\"></p><p>上映时间：2014年</p><p>Vivien Lesnik Weisman 的《黑客大战》探索骇客主义的核心问题，通过揭露他们的动机以及致力于社会政治活动大阴谋背后的目的。</p><p>电影反映那些和骇客活动联系在一起的年轻无政府力量，还有那些选择或者别无选择而不再藏匿在暗处的骇客分子们。这些故事来自于那些曾经被监禁或者正在被监禁的骇客们，该影片以其独特的视角描述整个运动和参与者的个人观点。</p><h3>20. 黑客所想（<a href=\"http://www.imdb.com/title/tt2292707/\">Hackers Wanted</a>）</h3><p><img width=\"350\" alt=\"20170617135706.jpg\" src=\"http://image.3001.net/images/20170617/14976790587745.jpg!small\"></p><p>上映时间：2009年</p><p>纪录片主要讲述了著名灰帽黑客艾德里安拉莫，并由拉莫亲自讲述。黑客的历史和拉莫的生活。</p><h3>21.&nbsp;黑客秘史（<a href=\"http://www.imdb.com/title/tt2335921/\">The Secret History Of Hacking</a>）</h3><p><img width=\"350\" alt=\"20170617135137.jpg\" src=\"http://image.3001.net/images/20170617/1497678731104.jpg!small\"></p><p>上映时间：2001年</p><p>黑客秘密史是一部2001年的纪录片，主要讲述了上世纪70年代到90年代所发生的电脑黑客和社会工程学的黑客故事。特别是那位通过蓝盒子盗打电话的Crunch船长的故事。</p><h3>22. 零日（<a href=\"http://www.imdb.com/title/tt5446858/\">Zero Days</a>）</h3><p><img width=\"350\" alt=\"20170617133216.jpg\" src=\"http://image.3001.net/images/20170617/14976775974711.jpg!small\"></p><p>上映时间：2016年</p><p>一个全新型态的网路超级病毒，突然遍布全世界的电脑，一开始无伤大雅不受重视，直到随着时间累积，许多基础建设的系统都一一被攻击掌控，比过往任何一种病毒复杂几十倍，甚至可能全面瘫痪人们的生活。</p><p>随着深入调查，揭露这个超级病毒Stuxnet，背后竟是美国与伊朗战争行动的阴谋，伊朗核武危机无法以政治手段解决，美国便对伊朗的网路展开攻击。无法回头的网路攻击逐渐失控，人们生活中各式控制系统都备受威胁，包括发电、交通、通讯、ATM、医院都将不堪一击，网路安全问题全球都可能遭到入侵，下一次的世界大战危机似乎也一触即发。</p><h3>23. 奇点（<a href=\"http://www.imdb.com/title/tt2073120/\">The Singularity</a>）</h3><p><img width=\"333\" alt=\"MV5BMTgxNjI4MzY1NF5BMl5BanBnXkFtZTgwMzYyNjA2MDE@._V1_.jpg\" src=\"http://image.3001.net/images/20170617/14976776127846.jpg!small\"></p><p>上映时间：2012年</p><p>如果有一天人类能够创造出具有超过人类智慧的计算机系统，生物工程化我们的物种，并通过纳米技术重新设计事物。那么，我们的文明过程将会被改变。SINGULARITY回避了关于机器人与人类的科幻小说，提出了一个从基本问题开始的的辩论：我们想成为什么样的人类？</p><h3>24.&nbsp;互联网之子（<a href=\"http://www.imdb.com/title/tt3268458/\">The Internet’s Own Boy: The Story of Aaron Swartz</a>）</h3><p><img width=\"350\" alt=\"20170617133150.jpg\" src=\"http://image.3001.net/images/20170617/1497677624231.jpg!small\"></p><p>上映时间：2014年</p><p>《互联网之子》由Brian Knappenberger 执导。该纪录片用凝重和悲凉的视角来回顾计算机天才Swartz的一生，从童年到公众生活。纪录片汇集包括Swartz本人在内的多个采访，他的成就和参与的战争，以及导致他自杀的极具争议的起诉。</p><h3>25.&nbsp;魔鬼藏在同意书（<a href=\"http://www.imdb.com/title/tt2084953/\">Terms and Conditions May Apply</a>）</h3><p><img width=\"350\" alt=\"20170617133640.jpg\" src=\"http://image.3001.net/images/20170617/14976778301642.jpg!small\"></p><p>上映时间：2013年</p><p>本片探讨了互联网所谓的“免费”服务，以及日渐消失的网络隐私。人们在使用Google、Facebook这类网站，轻松点下“我同意”时，他们根本不知道自己失去的是什么。</p><h3>26. BBS纪录片（<a href=\"http://www.imdb.com/title/tt0460402/\">BBS: The Documentary</a>）</h3><p><img width=\"400\" alt=\"MV5BMTM2MTQzNTE3Nl5BMl5BanBnXkFtZTcwNTUwMDAzMQ@@._V1_.jpg\" src=\"http://image.3001.net/images/20170617/14976779222193.jpg!small\"></p><p>上映时间：2005年</p><p>该纪录片共有八集，其中包含了200个访谈，并采用了蒙太奇的手法将这些内容剪辑到了一起。影片主要讲述了导演杰森·斯科特（Jason Scott）负责拨号公告板系统25年的历史。该系统是调制解调器连接的计算机系统，可让其他人通过电话线连接到计算机，并留下信息和交易文件。</p><h3>27.&nbsp;正版，盗版（<a href=\"http://www.imdb.com/title/tt1782451/\">Good Copy Bad Copy</a>）</h3><p><img width=\"300\" alt=\"MV5BMGIwOTNjZTAtNTgzMC00YzhjLWI4NjQtM2RmN2EyM2IwYjNmXkEyXkFqcGdeQXVyMzU5MDY4MDE@._V1_.jpg\" src=\"http://image.3001.net/images/20170617/14976779409679.jpg!small\"></p><p>上映时间：2007年</p><p>这部纪录片探究了版权的公平利用和盗版之间模糊的界限，采访了艺术家兼制片人Danger Mouse，创作共享协议创始人Lawrence Lessig，以及Pirate Bay的几位建立者，MPAA的主席John Kennedy和美国电影协会主席Dan Glickmanhe。</p>', 'https://timgsa.baidu.com/timg?image&amp;quality=80&amp;size=b9999_10000&amp;sec=1518508719183&amp;di=4d65ccfedded478887af99df939df456&amp;imgtype=0&amp;src=http%3A%2F%2Fupload.qudong.com%2F2015%2F0127%2F1422328103739.jpg', '1', '34', '1518498666', '1518498765', '3916', '0', '', '0', '0', '', '', '', '1');
INSERT INTO `blog_article` VALUES ('345', '2018新年电影集合', '<p>【FLVIP】 新年电影合集</p><h1><span style=\"font-size: 16pt; color: rgb(254, 44, 35);\">更多资源欢迎加入Q群：515739643</span></h1><p><br></p><p><span style=\"font-size: 16pt; color: rgb(254, 44, 35);\">电影资源，线报活动等福利</span></p><p>如已经添加【FLVIP】福利Q群请勿重复添加，谢谢</p><p><br></p><p><span style=\"color: rgb(64, 62, 59);\">红海行动&nbsp;</span><a href=\"http://vip.okzybo.com/share/i6rLvXRaUJw83wQO\" target=\"_blank\">点我观看</a></p><p><strong style=\"color: rgb(254, 44, 35);\">捉妖记2：</strong><a href=\"http://v8.yongjiu8.com/share/EcyGnQBQ2cNBIDv2\" target=\"_blank\">点击观看</a></p><p><strong style=\"color: rgb(13, 0, 21);\">祖宗19代：</strong><a href=\"http://yj.yongjiu6.com/share/2M7f4LxoyJcS7bxh\" target=\"_blank\">点击观看</a></p><p>西游记女儿国：<a href=\"http://yj.yongjiu6.com:80/share/llTc7ssN77aYY4KD\" target=\"_blank\">点击观看</a></p><p><a href=\"http://yj.yongjiu6.com:80/share/cZ1taWC0PzV3IOjN\" target=\"_blank\"></a></p><p><strong style=\"color: rgb(254, 44, 35);\">灵魂摆渡·黄泉：</strong><a href=\"http://yj.yongjiu6.com:80/share/tHXTx1fxr4LjmgH7\" target=\"_blank\"><strong>点击观看</strong></a></p><p>（<span style=\"color: rgb(85, 85, 85);\">主演:&nbsp;于毅,何花,王瑞昌,岳丽娜</span>）</p><p>妖妖零：<a href=\"http://yj.yongjiu6.com/share/5BTe6T8koKCku8jT\" target=\"_blank\">点击观看</a></p><p>（<span style=\"color: rgb(85, 85, 85);\">主演:&nbsp;吴君如,沈腾,岳云鹏,张译</span>）</p><p><span style=\"color: rgb(254, 44, 35);\">南极之恋：</span><a href=\"http://v8.yongjiu8.com/share/6MC72pOeU4313wZv\" target=\"_blank\">点击观看</a></p><p><span style=\"color: rgb(254, 44, 35);\">（</span><span style=\"color: rgb(85, 85, 85);\">主演:&nbsp;赵又廷,杨子姗</span><span style=\"color: rgb(254, 44, 35);\">）</span></p><p>死亡飞车4（高清）：<a href=\"http://yj.yongjiu6.com/share/bNN9bt7EOEpOaoWT\" target=\"_blank\">点击观看</a></p><p>妖猫传【高清】：<a href=\"http://yj.yongjiu6.com/share/PxTc4u8uGrnE6oWI\" target=\"_blank\">点击观看</a></p><p>（<span style=\"color: rgb(85, 85, 85);\">主演:&nbsp;黄轩,染谷将太,张雨绮,秦昊</span>）</p><p>白日焰火【高清】：<a href=\"http://yj.yongjiu6.com