INSERT INTO `blog_article` VALUES ('347', '关于短信轰炸机和怡红院更新说明', '<h3>之前收到消息说某轰炸机作者被抓且被判3年没当回事，如今证实了这个消息。</h3><h3>以后本人不会再写任何关于短信轰炸 电话轰炸 怡红院之类的手机电脑软件或者网页</h3><h3>特此发出声明 望悉知。</h3><h3>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;2018.2.19 &nbsp; 飞龙</h3>', 'http://img05.tooopen.com/images/20150807/tooopen_sy_137018855698.jpg', '1', '33', '1519013693', '1529116972', '1798', '0', '', '0', '0', '', '', '', '1');
INSERT INTO `blog_article` VALUES ('348', '坦白说查看器电脑版（6月9日更新版本）', '<p>登录就可以 没什么技巧 有时间会做安卓版本的</p><p><br></p><p>点击下载附件即可</p>', 'https://feilongwl.cn/Public/Uploads/2018-04-07/5ac83c170ba08.png', '1', '25', '1523072071', '1529116965', '3881', '0', '', '0', '0', '', '', './Public/Uploads/2018-06-09/5b1b63c02aff5.rar', '1');
INSERT INTO `blog_article` VALUES ('349', '[教程]在线解密QQ坦白说', '<h2>QQ坦白说</h2><p>划重点，先模拟UA然后再进入坦白说！<br>进入地址：<a href=\"https://ti.qq.com/honest-say/main.html\" target=\"_blank\">https://ti.qq.com/honest-say/main.html</a></p><h2>模拟QQ内置浏览器</h2><p>首先你的浏览器是可以模拟手机的<br>我这里用的 Chrome 谷歌浏览器</p><p>然后浏览器里面按F12,模拟手机<br>添加新模拟信息，User ag就复制下面的</p><p><code>ozilla/5.0 (iPhone; CPU iPhone OS 11_3 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Mobile/15E5216a QQ/7.5.5.426 V1_IPH_SQ_7.5.5_1_APP_A Pixel/1080 Core/UIWebView Device/Apple(iPhone 8Plus) NetType/WIFI QBWebViewType/1</code></p><p><img src=\"https://i.loli.net/2018/04/03/5ac3830ea1181.png\" alt=\"1.png\"><br><img src=\"https://i.loli.net/2018/04/03/5ac3830d427b1.png\" alt=\"2.png\"><br><img src=\"https://i.loli.net/2018/04/03/5ac3830ddc49f.png\" alt=\"3.png\"></p><h2>获取坦白说数据</h2><p>然后打开 坦白说页面<br><a href=\"https://ti.qq.com/honest-say/my-received.html\" target=\"_blank\">https://ti.qq.com/honest-say/my-received.html</a><br>注意，需要模拟手机QQ内置浏览器才可以</p><p>打开之后，如果一片空白，请再开一个新标签，登录QQ空间或者QQ邮箱，再刷新坦白说页面，这下就有数据了<br><img src=\"https://i.loli.net/2018/04/03/5ac37a911665e.png\" alt=\"坦白说\"></p><p>然后打开F12 工作台网络<br><img src=\"https://i.loli.net/2018/04/03/5ac37b268f0b7.png\" alt=\"\"></p><pre><code>复制 fromEncodeUin 这里字段里面的值\r\n类似<span class=\"hljs-symbol\" style=\"color: rgb(0, 176, 232);\">:*S1*owCl7evACCCCCC</span>\r\n然后*S1*不保留\r\n</code></pre><p><img src=\"https://i.loli.net/2018/04/03/5ac38cb23eb51.gif\" alt=\"\"></p><h2>在线解密</h2><p>打开<br><a href=\"https://tai7sy.github.io/honest-say/index.html\" target=\"_blank\">https://tai7sy.github.io/honest-say/index.html</a><br>如果打开不了 就打开下面这个<br>打开<br><a href=\"https://09l.me/tbs.html\" target=\"_blank\">https://09l.me/tbs.html</a><br>贴入owCl7evACCCCCC<br>即可得到QQ号码<br><img src=\"https://i.loli.net/2018/04/03/5ac37c509361b.png\" alt=\"\"></p><h2>解密代码</h2><pre><code><span class=\"hljs-keyword\" style=\"color: rgb(0, 0, 255);\">const</span> table = {<span class=\"hljs-string\" style=\"color: rgb(163, 21, 21);\">\"oe\"</span>: <span class=\"hljs-number\">0</span>, <span class=\"hljs-string\" style=\"color: rgb(163, 21, 21);\">\"n\"</span>: <span class=\"hljs-number\">0</span>, <span class=\"hljs-string\" style=\"color: rgb(163, 21, 21);\">\"z\"</span>: <span class=\"hljs-number\">0</span>,\r\n     <span class=\"hljs-string\" style=\"color: rgb(163, 21, 21);\">\"oK\"</span>: <span class=\"hljs-number\">1</span>, <span class=\"hljs-string\" style=\"color: rgb(163, 21, 21);\">\"6\"</span>: <span class=\"hljs-number\">1</span>, <span class=\"hljs-string\" style=\"color: rgb(163, 21, 21);\">\"5\"</span>: <span class=\"hljs-number\">1</span>,\r\n     <span class=\"hljs-string\" style=\"color: rgb(163, 21, 21);\">\"ow\"</span>: <span class=\"hljs-number\">2</span>, <span class=\"hljs-string\" style=\"color: rgb(163, 21, 21);\">\"-\"</span>: <span class=\"hljs-number\">2</span>, <span class=\"hljs-string\" style=\"color: rgb(163, 21, 21);\">\"A\"</span>: <span class=\"hljs-number\">2</span>,\r\n     <span class=\"hljs-string\" style=\"color: rgb(163, 21, 21);\">\"oi\"</span>: <span class=\"hljs-number\">3</span>, <span class=\"hljs-string\" style=\"color: rgb(163, 21, 21);\">\"o\"</span>: <span class=\"hljs-number\">3</span>, <span class=\"hljs-string\" style=\"color: rgb(163, 21, 21);\">\"i\"</span>: <span class=\"hljs-number\">3</span>,\r\n     <span class=\"hljs-string\" style=\"color: rgb(163, 21, 21);\">\"7e\"</span>: <span class=\"hljs-number\">4</span>, <span class=\"hljs-string\" style=\"color: rgb(163, 21, 21);\">\"v\"</span>: <span class=\"hljs-number\">4</span>, <span class=\"hljs-string\" style=\"color: rgb(163, 21, 21);\">\"P\"</span>: <span class=\"hljs-number\">4</span>,\r\n     <span class=\"hljs-string\" style=\"color: rgb(163, 21, 21);\">\"7K\"</span>: <span class=\"hljs-number\">5</span>, <span class=\"hljs-string\" style=\"color: rgb(163, 21, 21);\">\"4\"</span>: <span class=\"hljs-number\">5</span>, <span class=\"hljs-string\" style=\"color: rgb(163, 21, 21);\">\"k\"</span>: <span class=\"hljs-number\">5</span>,\r\n     <span class=\"hljs-string\" style=\"color: rgb(163, 21, 21);\">\"7w\"</span>: <span class=\"hljs-number\">6</span>, <span class=\"hljs-string\" style=\"color: rgb(163, 21, 21);\">\"C\"</span>: <span class=\"hljs-number\">6</span>, <span class=\"hljs-string\" style=\"color: rgb(163, 21, 21);\">\"s\"</span>: <span class=\"hljs-number\">6</span>,\r\n     <span class=\"hljs-string\" style=\"color: rgb(163, 21, 21);\">\"7i\"</span>: <span class=\"hljs-number\">7</span>, <span class=\"hljs-string\" style=\"color: rgb(163, 21, 21);\">\"S\"</span>: <span class=\"hljs-number\">7</span>, <span class=\"hljs-string\" style=\"color: rgb(163, 21, 21);\">\"l\"</span>: <span class=\"hljs-number\">7</span>,\r\n     <span class=\"hljs-string\" style=\"color: rgb(163, 21, 21);\">\"Ne\"</span>: <span class=\"hljs-number\">8</span>, <span class=\"hljs-string\" style=\"color: rgb(163, 21, 21);\">\"c\"</span>: <span class=\"hljs-number\">8</span>, <span class=\"hljs-string\" style=\"color: rgb(163, 21, 21);\">\"F\"</span>: <span class=\"hljs-number\">8</span>,\r\n     <span class=\"hljs-string\" style=\"color: rgb(163, 21, 21);\">\"NK\"</span>: <span class=\"hljs-number\">9</span>, <span class=\"hljs-string\" style=\"color: rgb(163, 21, 21);\">\"E\"</span>: <span class=\"hljs-number\">9</span>, <span class=\"hljs-string\" style=\"color: rgb(163, 21, 21);\">\"q\"</span>: <span class=\"hljs-number\">9</span>,\r\n     <span class=\"hljs-string\" style=\"color: rgb(163, 21, 21);\">\'*\'</span>: <span class=\"hljs-string\" style=\"color: rgb(163, 21, 21);\">\'X\'</span>};\r\n</code></pre><h2>原作者</h2><p>源代码来自 GitHub 作者<a href=\"https://github.com/Tai7sy/honest-say\" target=\"_blank\">@风铃</a><br>最后感谢作者的代码共享。</p><p>本博文转载自 双木\'sBlog</p>', 'https://i.loli.net/2018/04/03/5ac3780b57cb8.png', '1', '22', '1528759572', '1529116954', '2111', '0', '', '0', '0', '', '', '', '1');
