INSERT INTO `blog_article` VALUES ('351', '分期乐注册撸30QB或者话费等福利', '<h1>分期乐注册撸30话费或者QB：</h1><p><span style=\"font-size: 11pt;\">条件：成年</span><span style=\"font-size: 11pt;\"> </span><span style=\"font-size: 11pt;\">没有注册过乐卡</span></p><p><span style=\"font-size: 11pt;\">准备：身份证</span><span style=\"font-size: 11pt;\"> </span><span style=\"font-size: 11pt;\">银行卡</span><span style=\"font-size: 11pt;\"> </span><span style=\"font-size: 11pt;\">微信（需要绑定本人实名认证）</span></p><p><span style=\"font-size: 11pt;\">活动时间：</span><span style=\"font-size: 11pt;\">6</span><span style=\"font-size: 11pt;\">月</span><span style=\"font-size: 11pt;\">1</span><span style=\"font-size: 11pt;\">日到</span><span style=\"font-size: 11pt;\">6</span><span style=\"font-size: 11pt;\">月</span><span style=\"font-size: 11pt;\">30</span><span style=\"font-size: 11pt;\">日</span></p><p><span style=\"font-size: 14pt;\">步骤</span><span style=\"font-size: 14pt;\"> </span><span style=\"font-size: 14pt;\">：手机微信扫码进入下载</span><span style=\"font-size: 14pt;\">APP-&gt;</span><span style=\"font-size: 14pt;\">短信登录</span><span style=\"font-size: 14pt;\">-&gt;</span><span style=\"font-size: 14pt;\">点击乐卡</span><span style=\"font-size: 14pt;\">-&gt;</span><span style=\"font-size: 14pt;\">开通乐卡</span></p><p><span style=\"font-size: 14pt;\"><span style=\"font-size: 14pt;\"><img width=\"271\" height=\"279\" src=\"https://feilongwl.cn/Public/Uploads/2018-06-15/5b231dce66f92.png\"></span></span></p><p><span style=\"font-size: 14pt;\">开通成功后</span><span style=\"font-size: 14pt;\">-&gt;</span><span style=\"font-size: 14pt;\">按提示进行借款操作</span><span style=\"font-size: 14pt;\"> </span><span style=\"font-size: 14pt;\">借</span><span style=\"font-size: 14pt;\">1500 </span></p><h3><span style=\"font-size: 14pt;\"><b>提示一下：这里的一千五是根据额度来借的 你的额度比较少就借1000元也是没有关系的 主要是完成借还这个流程，走个形式</b></span></h3><p><b><span style=\"font-size: 12pt; color: rgb(255, 0, 0);\">一定要使用免息券</span></b><b></b></p><p><b><span style=\"font-size: 12pt; color: rgb(255, 0, 0);\">一定要使用免息券</span></b><b></b></p><p><b><span style=\"font-size: 12pt; color: rgb(255, 0, 0);\">一定要使用免息券</span></b><b></b></p><p><span style=\"font-size: 14pt;\">接下来不到</span><span style=\"font-size: 14pt;\">1</span><span style=\"font-size: 14pt;\">分钟借的钱就到你的银行卡里面了</span><span style=\"font-size: 14pt;\"> </span><span style=\"font-size: 14pt;\">然后去还款还</span><span style=\"font-size: 14pt;\">1500</span></p><p><span style=\"font-size: 14pt;\">等于是秒借秒还走个流程</span><span style=\"font-size: 14pt;\"> </span><span style=\"font-size: 14pt;\">然后你会有一张满</span><span style=\"font-size: 14pt;\">30-29.99</span><span style=\"font-size: 14pt;\">的优惠券</span><span style=\"font-size: 14pt;\"> </span><span style=\"font-size: 14pt;\">去充话费</span><span style=\"font-size: 14pt;\"> Qb</span></p><p><span style=\"font-size: 14pt;\">或者王者点券都可以</span></p><p><span style=\"font-size: 14pt;\">&nbsp;</span></p><p><span style=\"font-size: 14pt;\">注意：</span><span style=\"font-size: 14pt;\">QB</span><span style=\"font-size: 14pt;\">可以兑换为现金</span><span style=\"font-size: 14pt;\"> 8</span><span style=\"font-size: 14pt;\">折回收</span><span style=\"font-size: 14pt;\">&nbsp; </span></p><p><span style=\"font-size: 14pt;\">另外</span><span style=\"font-size: 14pt;\"> </span><span style=\"font-size: 14pt;\">可以邀请现实好友参加活动可以另外获得更多福利</span><span style=\"font-size: 14pt;\"> </span><span style=\"font-size: 14pt;\">详情请看分期乐</span><span style=\"font-size: 14pt;\"> - </span><span style=\"font-size: 14pt;\">立即邀请里面的说明</span><span style=\"font-size: 14pt;\">.</span></p><p><span style=\"font-size: 14pt;\"><br></span></p><p>&nbsp;<img alt=\"0B154DEF9BD14E659C22EE8DE30BF47C.jpg\" src=\"https://feilongwl.cn/Public/Uploads/2018-06-15/5b231dd8af7ab.jpg\" width=\"287\" height=\"510\"><img alt=\"A5F4E5082119490E89D13D424060D5D6.jpg\" src=\"https://feilongwl.cn/Public/Uploads/2018-06-15/5b231de8cad39.jpg\" width=\"261\" height=\"510\"><img alt=\"5E73E3332098430AB3C2F79FA82B80DC.jpg\" src=\"https://feilongwl.cn/Public/Uploads/2018-06-15/5b231dff1b8a0.jpg\" width=\"286.78670360110806\" height=\"510\"></p>', 'https://feilongwl.cn/Public/Uploads/2018-06-15/5b231d75482f5.jpg', '1', '43', '1529028110', '1530409362', '1578', '0', '', '0', '0', '', '', '', '1');
INSERT INTO `blog_article` VALUES ('352', '懂球帝填邀请得红包 亲测1.14 元', '<h1><span style=\"font-size: 15px;\">步骤如下：</span></h1><h1><span style=\"font-size: 15px;\">1、打开：<b><a href=\"https://m.dongqiudi.com/app/\" target=\"_blank\">https://m.dongqiudi.com/app/</a>&nbsp;</b>下载 左上角注册帐号，如果注册时接码频繁</span></h1><h1><span style=\"font-size: 15px;\">2、打开飞行模式，退出软件后台重新打开，然后到注册接验证码哪个页面，开流量接码就行</span></h1><h1><span style=\"font-size: 15px;\">3、然后点击“邀请得现金”左上角“填写邀请码”输入&nbsp;</span><span style=\"font-size: 15px;\"><b>501467&nbsp;</b></span><span style=\"font-size: 15px;\">然后退出页面重新进</span></h1><h1><span style=\"font-size: 15px;\">4、点击下方提现，授权下支付宝，秒到账，大家可以评论发出自己的邀请码不必填页面的</span></h1>', 'https://feilongwl.cn/Public/Uploads/2018-06-16/5b245c2cc15d0.jpg', '1', '43', '1529109662', '1529116913', '1413', '0', '', '0', '0', '', '', '', '1');
