INSERT INTO `blog_article` VALUES ('359', '佛山人才网答题抽包', '<p><span style=\"color: rgb(105, 105, 105); font-size: 14px;\"><img alt=\"Image\" src=\"http://www.rjk6.com/uploads/images/34d372ba2943f5fa853d38de4b500cbe.png\" width=\"480\" height=\"853.3333333333334\"><br></span></p><p><span style=\"color: rgb(105, 105, 105); font-size: 14px;\"><br></span></p><p><span style=\"color: rgb(105, 105, 105); font-size: 14px;\"><br></span></p><h1><span style=\"color: rgb(105, 105, 105); font-size: 14px;\">微信扫码关注【佛山人才网】并点击菜单栏【公共服务】-【有奖问答】参与</span></h1><h1><span style=\"color: rgb(105, 105, 105); font-size: 14px;\">小编提示：系统随机抽5题全部答对可进行抽奖，红包非必中，也可多留意下放水消息</span></h1><h1><span style=\"color: rgb(105, 105, 105); font-size: 14px;\">须知：每个微信号每天有5次答题机会，在活动页面查看攻略页面直接下拉至底部进去答题，不定时放水</span></h1>', 'http://www.rjk6.com/uploads/images/34d372ba2943f5fa853d38de4b500cbe.png', '1', '43', '1529372481', '1529372481', '1122', '0', '', '0', '1', '', '', '', '1');
INSERT INTO `blog_article` VALUES ('360', '支付宝：每天搜索数字口令，领取随机现金红包', '<p>&nbsp;另外告诉大家一个每天自己快速领快速套现的小技巧</p><p>打开：<a href=\"https://cli.im/deqr\" target=\"_blank\">https://cli.im/deqr</a>（去把领红包和收款的二维码转为链接，发送给支付宝好友）</p><p>这样每天直接在支付宝APP点链接，然后直接套现，稳如狗的，不用在去扫码那么麻烦</p><p>建议大家2个支付宝互相套这样</p><p>补充一个收款码申请地址：<a href=\"https://b.alipay.com/settling/tc/entry.htm\" target=\"_blank\">https://b.alipay.com/settling/tc/entry.htm</a></p><p>6月20日重新发，最近几天大水，很多额外大包</p><p>领到打宝去和朋友一起套现 &nbsp;去申请收款码的那个地方可以选择<span style=\"color: rgb(227, 55, 55);\">偏远地区</span></p><p>自行打印二维码&nbsp;就可以收取商户红包了&nbsp;无需等待和支付3元领取&nbsp;<br></p>', 'https://feilongwl.cn/Public/Uploads/2018-06-20/5b2a2c04e7d78.jpg', '1', '43', '1529490532', '1529492574', '3544', '0', '', '0', '0', '', '', '', '1');
