INSERT INTO `blog_article` VALUES ('466', '[2018.11.23]分期乐注册撸30QB或者话费等福利', '<p>截止到2018.11.23 - 25 走我的个人链接 可以撸平台30 另外我返30</p><p><b>复制链接：<a href=\"http://t.cn/E2kIBvM\" target=\"_blank\">&nbsp;http://t.cn/E2kIBvM</a></b></p><p><span style=\"color: rgb(0, 0, 0); font-size: 24px;\"><br></span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 24px;\">分期乐注册撸30话费或者QB：</span><br></p><p><span style=\"font-size: 11pt;\">条件：成年</span><span style=\"font-size: 11pt;\">&nbsp;</span><span style=\"font-size: 11pt;\">没有注册过乐卡</span></p><p><span style=\"font-size: 11pt;\">准备：身份证</span><span style=\"font-size: 11pt;\">&nbsp;</span><span style=\"font-size: 11pt;\">银行卡</span><span style=\"font-size: 11pt;\">&nbsp;</span><span style=\"font-size: 11pt;\">微信（需要绑定本人实名认证）</span></p><p><span style=\"font-size: 14pt;\">步骤</span><span style=\"font-size: 14pt;\">&nbsp;</span><span style=\"font-size: 14pt;\">：手机微信扫码进入下载</span><span style=\"font-size: 14pt;\">APP-&gt;</span><span style=\"font-size: 14pt;\">短信登录</span><span style=\"font-size: 14pt;\">-&gt;</span><span style=\"font-size: 14pt;\">点击乐卡</span><span style=\"font-size: 14pt;\">-&gt;</span><span style=\"font-size: 14pt;\">开通乐卡</span></p><p><span style=\"font-size: 14pt;\"><span style=\"font-size: 14pt;\"><img width=\"260\" height=\"260\" src=\"https://feilongwl.cn/Public/Uploads/2018-11-23/5bf7a07fb8728.png\"></span></span></p><p><span style=\"font-size: 14pt;\">开通成功后</span><span style=\"font-size: 14pt;\">-&gt;</span><span style=\"font-size: 14pt;\">按提示进行借款操作</span><span style=\"font-size: 14pt;\">&nbsp;</span><span style=\"font-size: 14pt;\">借指定额度的钱&nbsp;</span></p><h3><span style=\"font-size: 14pt;\"><b>提示一下：这里的一千五是根据额度来借的 你的额度比较少就借1000元也是没有关系的 主要是完成借还这个流程，走个形式</b></span></h3><p><b><span style=\"font-size: 12pt; color: rgb(255, 0, 0);\">一定要使用免息券</span></b></p><p><b><span style=\"font-size: 12pt; color: rgb(255, 0, 0);\">一定要使用免息券</span></b></p><p><b><span style=\"font-size: 12pt; color: rgb(255, 0, 0);\">一定要使用免息券</span></b></p><p><span style=\"font-size: 14pt;\">接下来不到</span><span style=\"font-size: 14pt;\">1</span><span style=\"font-size: 14pt;\">分钟借的钱就到你的银行卡里面了</span><span style=\"font-size: 14pt;\">&nbsp;</span><span style=\"font-size: 14pt;\">然后去还款还</span><span style=\"font-size: 14pt;\">1500</span></p><p><span style=\"font-size: 14pt;\">等于是秒借秒还走个流程</span><span style=\"font-size: 14pt;\">&nbsp;</span><span style=\"font-size: 14pt;\">然后你会有一张满</span><span style=\"font-size: 14pt;\">30-29.99</span><span style=\"font-size: 14pt;\">的优惠券</span><span style=\"font-size: 14pt;\">&nbsp;</span><span style=\"font-size: 14pt;\">去充话费</span><span style=\"font-size: 14pt;\">&nbsp;Qb&nbsp;</span><span style=\"font-size: 14pt;\">或者王者点券都可以</span></p><p><br></p><p><span style=\"font-size: 14pt;\">注意：</span><span style=\"font-size: 14pt;\">QB</span><span style=\"font-size: 14pt;\">可以兑换为现金</span><span style=\"font-size: 14pt;\">&nbsp;8</span><span style=\"font-size: 14pt;\">折回收</span><span style=\"font-size: 14pt;\">&nbsp;</span></p><p><span style=\"font-size: 14pt;\">另外</span><span style=\"font-size: 14pt;\">&nbsp;</span><span style=\"font-size: 14pt;\">可以邀请现实好友参加活动可以另外获得更多福利</span><span style=\"font-size: 14pt;\">&nbsp;</span><span style=\"font-size: 14pt;\">详情请看分期乐</span><span style=\"font-size: 14pt;\">&nbsp;-&nbsp;</span><span style=\"font-size: 14pt;\">立即邀请里面的说明</span><span style=\"font-size: 14pt;\">.</span></p><p><span style=\"font-size: 14pt;\"><br></span></p><p>&nbsp;<img alt=\"0B154DEF9BD14E659C22EE8DE30BF47C.jpg\" src=\"http://feilongwl.cn/Public/Uploads/2018-06-15/5b231dd8af7ab.jpg\" width=\"287\" height=\"510\"><img alt=\"A5F4E5082119490E89D13D424060D5D6.jpg\" src=\"http://feilongwl.cn/Public/Uploads/2018-06-15/5b231de8cad39.jpg\" width=\"261\" height=\"510\"><img alt=\"5E73E3332098430AB3C2F79FA82B80DC.jpg\" src=\"http://feilongwl.cn/Public/Uploads/2018-06-15/5b231dff1b8a0.jpg\" width=\"286.78670360110806\" height=\"510\"></img></p>', 'https://feilongwl.cn/Public/Uploads/2018-06-15/5b231d75482f5.jpg', '1', '43', '1542955211', '1542955211', '1724', '0', '', '0', '0', '', '', '', '1');
INSERT INTO `blog_article` VALUES ('467', 'Smali基本语法', '<p style=\"margin-left: auto;\">.field private isFlag:z　　定义变量</p><p style=\"margin-left: auto;\">.method　　方法</p><p style=\"margin-left: auto;\">.parameter　　方法参数</p><p style=\"margin-left: auto;\">.prologue　　方法开始</p><p style=\"margin-left: auto;\">.line 12　　此方法位于第12行</p><p style=\"margin-left: auto;\">invoke-super　　调用父函数</p><p style=\"margin-left: auto;\">const/high16 &nbsp;v0, 0x7fo3　　把0x7fo3赋值给v0</p><p style=\"margin-left: auto;\">invoke-direct　　调用函数</p><p style=\"margin-left: auto;\">return-void　　函数返回void</p><p style=\"margin-left: auto;\">.end method　　函数结束</p><p style=\"margin-left: auto;\">new-instance　　创建实例</p><p style=\"margin-left: auto;\">iput-object　　对象赋值</p><p style=\"margin-left: auto;\">iget-object　　调用对象</p><p style=\"margin-left: auto;\">invoke-static　　调用静态函数</p><p style=\"margin-left: auto;\"><br></p><hr><pre><code>个人常用总结：\r\n\r\n赋值真 const/4 v0,v0 0x1\r\n赋值字符串 const-string v0, \"0\"</code></pre><hr><p style=\"margin-left: auto;\"><span style=\"font-size: 18pt;\"><strong><span style=\"color: rgb(0, 0, 0);\">条件跳转分支：</span></strong></span></p><p><br></p><pre><code>\"if-eq vA, vB, :cond_**\"&nbsp; &nbsp;如果vA等于vB则跳转到:cond_**\r\n\"if-ne&nbsp;vA, vB, :cond_**\"&nbsp; &nbsp;如果vA不等于vB则跳转到:cond_**\r\n\"if-lt&nbsp;vA, vB, :cond_**\"&nbsp; &nbsp;&nbsp;如果vA小于vB则跳转到:cond_**\r\n\"if-ge&nbsp;vA, vB, :cond_**\"&nbsp; &nbsp;如果vA大于等于vB则跳转到:cond_**\r\n\"if-gt&nbsp;vA, vB, :cond_**\"&nbsp; &nbsp;如果vA大于vB则跳转到:cond_**\r\n\"if-le&nbsp;vA, vB, :cond_**\"&nbsp; &nbsp;&nbsp;如果vA小于等于vB则跳转到:cond_**\r\n\"if-eqz vA, :cond_**\"&nbsp; &nbsp;如果vA等于0则跳转到:cond_**\r\n\"if-nez&nbsp;vA, :cond_**\"&nbsp; &nbsp;如果vA不等于0则跳转到:cond_**\r\n\"if-ltz&nbsp;vA, :cond_**\"&nbsp; &nbsp;&nbsp;如果vA小于0则跳转到:cond_**\r\n\"if-gez&nbsp;vA, :cond_**\"&nbsp; &nbsp;如果vA大于等于0则跳转到:cond_**\r\n\"if-gtz&nbsp;vA, :cond_**\"&nbsp; &nbsp;如果vA大于0则跳转到:cond_**\r\n\"if-lez&nbsp;vA, :cond_**\"&nbsp; &nbsp;&nbsp;如果vA小于等于0则跳转到:cond_**<br></code></pre><p>if函数的java代码：<br></p><pre><code class=\"lang-java\">private boolean ifSense(){\r\n&nbsp; &nbsp; &nbsp; &nbsp; boolean tempFlag = ((3-2)==1)? true : false;\r\n&nbsp; &nbsp; &nbsp; &nbsp; if (tempFlag) {\r\n&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; return true;\r\n&nbsp; &nbsp; &nbsp; &nbsp; }else{\r\n&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; return false;\r\n&nbsp; &nbsp; &nbsp; &nbsp; }\r\n&nbsp; &nbsp; }<br></code></pre><p>if函数分析：<br></p><pre><code class=\"lang-java\">.method private ifSense()Z\r\n&nbsp; &nbsp; .locals 2\r\n\r\n&nbsp; &nbsp; .prologue\r\n&nbsp; &nbsp; .line 22\r\n&nbsp; &nbsp; const/4 v0, 0x1 &nbsp; &nbsp; // v0赋值为1\r\n\r\n&nbsp; &nbsp; .line 24\r\n&nbsp; &nbsp; .local v0, tempFlag:Z\r\n&nbsp; &nbsp; if-eqz v0, :cond_0 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;// 判断v0是否等于0, 不符合条件向下走, 符合条件执行cond_0分支\r\n\r\n&nbsp; &nbsp; .line 25\r\n&nbsp; &nbsp; const/4 v1, 0x1 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;// 符合条件分支\r\n\r\n&nbsp; &nbsp; .line 27\r\n&nbsp; &nbsp; :goto_0\r\n&nbsp; &nbsp; return v1\r\n\r\n&nbsp; &nbsp; :cond_0\r\n&nbsp; &nbsp; const/4 v1, 0x0 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;// cond_0分支\r\n\r\n&nbsp; &nbsp; goto :goto_0\r\n.end method\r\n\r\n###文字描述：如果符合if分支则程序往下走，最终return ; 而如果条件不符合则会走到 :cond_0分支 , 最终执行 goto :goto_0走回 :goto_0返回<br></code></pre><p><br></p><p><br></p><hr><p><br></p><p>for函数java代码：<br></p><pre><code class=\"lang-java\">private void forSense(){\r\n    listStr = new ArrayList<string>(COUNT);\r\n    for (int i = 0; i &lt; COUNT; i++) {\r\n        listStr.add(\"test\");\r\n    }\r\n}<br></string></code></pre><p><br></p><p>for函数分析：</p><pre><code>.line 40\r\n&nbsp; &nbsp; const/4 v0, 0x0\r\n\r\n&nbsp; &nbsp; .local v0, i:I\r\n&nbsp; &nbsp; :goto_0\r\n&nbsp; &nbsp; if-lt v0, v3, :cond_0 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;// &nbsp;if-lt判断数值v0小于v3 , &nbsp; &nbsp;如不符合往下走, 符合执行分支 :cond_0\r\n\r\n&nbsp; &nbsp; .line 43\r\n&nbsp; &nbsp; return-void\r\n\r\n&nbsp; &nbsp; .line 41\r\n&nbsp; &nbsp; :cond_0 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;// 标签\r\n&nbsp; &nbsp; iget-object v1, p0, Lcom/example/smalidemo/MainActivity;-&gt;listStr:Ljava/util/List; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;// 引用对象\r\n\r\n&nbsp; &nbsp; const-string v2, \"\\u73b0\\u5728\\u8f6e\\u5230\\u6211\\u4e0a\\u573a\\u4e50\"\r\n\r\n&nbsp; &nbsp; invoke-interface {v1, v2}, Ljava/util/List;-&gt;add(Ljava/lang/Object;)Z &nbsp; &nbsp; &nbsp; &nbsp;// List是接口, 所以执行接口方法add\r\n\r\n&nbsp; &nbsp; .line 40\r\n&nbsp; &nbsp; add-int/lit8 v0, v0, 0x1　　　　// 将第二个v0寄存器中的值，加上0x1的值放入第一个寄存器中, 实现自增长\r\n\r\n&nbsp; &nbsp; goto :goto_0 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;// 回去:goto_0标签\r\n\r\n＃＃＃文字描述：设定一个标签goto_0, 判断v0小于v3, 符合执行分支:cond_0 ,然后又跑回:goto_0做继续判断</code></pre>', 'https://feilongwl.cn/Public/Uploads/2018-12-23/5c1f9c2f05c1e.png', '1', '22', '1545575478', '1547298089', '1704', '0', '', '1', '0', '', '', '', '1');
INSERT INTO `blog_article` VALUES ('468', 'Android特征总结整理', '<pre><code>360\r\nassets/.appkey\r\nassets/libjiagu.so<br></code></pre><p><br></p><pre><code>爱加密\r\nlib/armeabi/libexecmain.so\r\nassets/ijiami.ajm\r\nassets/af.bin\r\nassets/signed.bin\r\nassets/ijm_lib/armeabi/libexec.so\r\nassets/ijm_lib/X86/libexec.so<br></code></pre><pre><code>几维安全\r\nassets/dex.dat\r\nlib/armeabi/kdpdata.so\r\nlib/armeabi/libkdp.so\r\nlib/armeabi/libkwscmm.so<br></code></pre><pre><code>梆梆安全\r\n免费版\r\nassets/secData0.jar\r\nlib/armeabi/libSecShell.so\r\nlib/armeabi/libSecShell-x86.so\r\n定制版\r\nassets/classes.jar\r\nlib/armeabi/DexHelper.so<br></code></pre><pre><code>腾讯加固\r\ntencent_stub\r\nlib/armeabi/libshella-xxxx.so\r\nlib/armeabi/libshellx-xxxx.so\r\nlib/armeabi/mix.dex\r\nlib/armeabi/mixz.dex<br></code></pre><pre><code>腾讯御安全\r\nassets/libtosprotection.armeabi-v7a.so\r\nassets/libtosprotection.armeabi.so\r\nassets/libtosprotection.x86.so\r\nassets/tosversion\r\nlib/armeabi/libtest.so\r\nlib/armeabi/libTmsdk-xxx-mfr.so<br></code></pre><pre><code>顶象技术\r\nlib/armeabi/libx3g.so<br></code></pre><pre><code>阿里加固\r\nassets/armeabi/libfakejni.so\r\nassets/armeabi/libzuma.so\r\nassets/libzuma.so\r\nassets/libzumadata.so\r\nassets/libpreverify1.so\r\ndexprotect\r\nassets/classes.dex.dat\r\nassets/dp.arm-v7.so.dat\r\nassets/dp.arm.so.dat<br></code></pre><pre><code>百度加固\r\nlib/armeabi/libbaiduprotect.so\r\nassets/baiduprotect1.jar\r\n或者\r\nassets/baiduprotect.jar<br></code></pre><p><br></p><pre><code>海云安加固\r\nassets/itse\r\nlib/armeabi/libitsec.so\r\napktoolplus\r\nassets/jiagu_data.bin\r\nassets/sign.bin\r\nlib/armeabi/libapktoolplus_jiagu.so<br></code></pre><pre><code>娜迦&nbsp;libedog.so/libddog.so<br></code></pre><pre><code>通付盾 libegis.so</code></pre><pre><code>瑞星加固 librsprotect.so</code></pre><pre><code>网秦加固 libnqshield.so</code></pre><pre><code>uu安全\r\nassets/libuusafe.jar.so\r\nassets/libuusafe.so\r\nlib/armeabi/libuusafeempty.so<br></code></pre><pre><code>中国移动加固\r\nassets/mogosec_classes\r\nassets/mogosec_data\r\nassets/mogosec_dexinfo\r\nassets/mogosec_march\r\nlib/armeabi/libcmvmp.so\r\nlib/armeabi/libmogosec_dex.so\r\nlib/armeabi/libmogosec_sodecrypt.so\r\nlib/armeabi/libmogosecurity.so<br></code></pre><pre><code>珊瑚灵御\r\nassets/libreincp.so\r\nassets/libreincp_x86.so<br></code></pre><p><br></p><p><br></p><hr><blockquote><p><b>部分壳的application</b><br></p></blockquote><pre><code>爱加密s.h.e.l.l.S\r\n360加固com.stub.StubApp\r\n几维安全com.Kiwisec.KiwiSecApplication\r\n或者com.Kiwisec.ProxyApplication\r\n或者干脆没有application\r\n梆梆安全com.secshell.secData.ApplicationWrapper\r\n腾讯加固com.tencent.StubShell.TxAppEntry\r\n海云安c.b.c.b\r\n腾讯御安全MyWrapperProxyApplication\r\n顶象技术cn.securitystack.stee.AppStub\r\napktoolplus com.linchaolong.apktoolplus.jiagu.ProxyApplication\r\n珊瑚灵御com.coral.util.StubApplication\r\n魔固云(中国移动加固)com.mogosec.AppMgr\r\n特别注意\r\napktool助手伪加固特征\r\n监测application即可\r\n假360加固\r\n没.appkey\r\napplication为com.qihoo.util.stub2678363137\r\n假梆梆加固\r\napplication为com.secoen.apkwrapper.ApplicationWrapper<br></code></pre><h1><br></h1>', 'https://feilongwl.cn/Public/Uploads/2019-01-01/5c2b4d395dae1.png', '1', '44', '1546341696', '1685467936', '3041', '0', '', '0', '1', '', '', '', '1');
INSERT INTO `blog_article` VALUES ('471', 'APICloud 从解密本地资源到逆向算法到通用解密', '<p>前言:昨天下午有群友问这个用 HTML 写的 APP 怎么逆向</p><p><img alt=\"1.png\" src=\"https://feilongwl.cn/Public/Uploads/2019-02-21/5c6e60110906d.png\" width=\"512\" height=\"632\"><br></p><p>当时就认出来了这是 APICloud(<a href=\"https://www.apicloud.com\" rel=\"nofollow\">https://www.apicloud.com</a>) 家的产品,网页转 APP,网页资源文件加密储存在本地 看下图:</p><p><img alt=\"2.png\" src=\"http://feilongwl.cn/Public/Uploads/2019-02-21/5c6e602037ce7.png\" width=\"1102\" height=\"437\"><br></p><p><br></p><p><img alt=\"3.png\" src=\"http://feilongwl.cn/Public/Uploads/2019-02-21/5c6e605b55b46.png\" width=\"1067\" height=\"369\"><br></p><p><br></p><p><font color=\"#e33737\"><b>下面开始分析:</b></font></p><p><font color=\"#e33737\"><b><br></b></font></p><p>1. 既然是网页实现就少不用 WEBVIEW X5 之类的框架来加载呈现 先看看界面的结构</p><p><img alt=\"5.png\" src=\"http://feilongwl.cn/Public/Uploads/2019-02-21/5c6e60a70f85a.png\" width=\"830\" height=\"751\"><br></p><p><br></p><p>是一个 WebView 控件,顺手就打开远程调试:</p><p><br></p><p><img alt=\"6.png\" src=\"https://feilongwl.cn/Public/Uploads/2019-02-21/5c6e60b969a99.png\" width=\"657\" height=\"411\"><br></p><p>很遗憾,在 WebView Debug = true 的情况下没有接入端口,只能从源代码分析了.</p><p><br></p><p>2. APP 并没有壳,直接 JEB 打开</p><p><img alt=\"7.png\" src=\"https://feilongwl.cn/Public/Uploads/2019-02-21/5c6e60e6b0a67.png\" width=\"1108\" height=\"542\"><br></p><p>结构也很简单,厂家的 SDK 占了大部分内容(因为是网页开发 APP,要逻辑都在 JS)</p><p>先思考 APP 对资源的加载流程</p><p>可能为:</p><p>1)WEBVIEW - &gt; 加载页面 -&gt; 拦截/查找本地文件 有 -&gt; 解密/写回数据</p><p>2)WEBVIEW - &gt; 加载页面 -&gt; 拦截/查找本地文件 无 -&gt; 请求网络文件</p><p><br></p><p>这里有个共同的点都是需要 拦截,而 WebView 只有一个实现这个功能的接口:WebViewClient.shouldInterceptRequest</p><p><br></p><p>下面是摘抄博客对 API 的介绍:</p><p><img alt=\"8.png\" src=\"https://feilongwl.cn/Public/Uploads/2019-02-21/5c6e6138dda29.png\" width=\"1120\" height=\"392\"><br></p><p>2.1 在 JEB 里面搜索这个方法:</p><p>下图:</p><p><img alt=\"9.png\" src=\"https://feilongwl.cn/Public/Uploads/2019-02-21/5c6e615f9b737.png\" width=\"1090\" height=\"594\"><br></p><p><br></p><p>只有这个地方有实现.继续往下看逻辑</p><p>a.d -&gt; z.a -&gt;</p><p><img alt=\"10.png\" src=\"https://feilongwl.cn/Public/Uploads/2019-02-21/5c6e6179e3106.png\" width=\"852\" height=\"124\"><br></p><p>获取 URL 的文件后缀.</p><p>a.e -&gt; z.d -&gt;&nbsp;</p><p><img alt=\"11.png\" src=\"https://feilongwl.cn/Public/Uploads/2019-02-21/5c6e618cebc84.png\" width=\"702\" height=\"138\"><br></p><p><img alt=\"12.png\" src=\"https://feilongwl.cn/Public/Uploads/2019-02-21/5c6e61a080f2f.png\" width=\"407\" height=\"297\"><br></p><p><br></p><p>判断是不是需要管理的 URL</p><p>This.b</p><p>this.a</p><p>分别处理俩种情况的文件:</p><p><img alt=\"13.png\" src=\"https://feilongwl.cn/Public/Uploads/2019-02-21/5c6e61c315437.png\" width=\"631\" height=\"636\"><br></p><p><br></p><p><img alt=\"14.png\" src=\"https://feilongwl.cn/Public/Uploads/2019-02-21/5c6e61d749d02.png\" width=\"546\" height=\"642\"><br></p><p><br></p><p>到了这里 SDK 接管资源的痕迹就很明显了,再往下我相信可以找到怎么加载&amp;解密文件但是我的目的只是 dump 出原来的明文资源就好,到这里就可以停止了</p><p><br></p><p>2.2 关注 new i(v1, new c(v2, v0)); 这行点进去看下:</p><p>是 WebResourceResponse(String mimeType, String encoding,InputStream data) 的实现</p><p>再往下就是 WebView 内部了,SDK 也没法做什么改变了,相信 InputStream 就是标准的数据了,从 new c(v2, v0) 入手用 Xposed Hook 出数据看一下.</p><p><img alt=\"16.png\" src=\"http://feilongwl.cn/Public/Uploads/2019-02-21/5c6e6213d69d0.png\" width=\"1381\" height=\"640\"><br></p><p>运行 APP,查看 Logcat</p><p><img alt=\"17.png\" src=\"https://feilongwl.cn/Public/Uploads/2019-02-21/5c6e6236d4ee9.png\" width=\"1380\" height=\"113\"><br></p><p>成功….</p><p>原来:</p><p><img alt=\"18.png\" src=\"https://feilongwl.cn/Public/Uploads/2019-02-21/5c6e624d3c372.png\" width=\"994\" height=\"710\"><br></p><p>DUMP:</p><p><img alt=\"19.png\" src=\"https://feilongwl.cn/Public/Uploads/2019-02-21/5c6e625ab9cfd.png\" width=\"1060\" height=\"625\"><br></p><p><br></p><p>3. 解密 APP&nbsp;</p><p>通讯数据抓包看下:</p><p><img alt=\"20.png\" src=\"http://feilongwl.cn/Public/Uploads/2019-02-21/5c6e626c359c9.png\" width=\"1375\" height=\"312\"><br></p><p>双向加密:</p><p>我们从 DUMP 出来的资源中搜索 “/api.php”</p><p><img alt=\"21.png\" src=\"https://feilongwl.cn/Public/Uploads/2019-02-21/5c6e6295a2c3a.png\" width=\"1059\" height=\"469\"><br></p><p>顺路发现了可能用来加解密的可疑算法..&nbsp;</p><p>来试试解请求:</p><p><img alt=\"22.png\" src=\"https://feilongwl.cn/Public/Uploads/2019-02-21/5c6e62a58dbd3.png\" width=\"1100\" height=\"405\"><br></p><p>解返回:</p><p><img alt=\"23.png\" src=\"https://feilongwl.cn/Public/Uploads/2019-02-21/5c6e62b3b1da7.png\" width=\"1099\" height=\"473\"><br></p><p>成功:</p><p>不得不说通讯用的加密算法就好像是路边捡回来的.</p><p><br></p><p>4. 制作通用工具</p><p>从前面的分析可以看出,SDK 是混淆过的</p><p><img alt=\"25.png\" src=\"https://feilongwl.cn/Public/Uploads/2019-02-21/5c6e62d1bec25.png\" width=\"581\" height=\"698\"><br></p><p>上面的 HOOK 只能针对某一个 APP,换个 APP 又得重新分析，如果 APP 加了壳那还得脱壳才能分析</p><p><br></p><p>下面给出通用的 DUMP 且无视加壳的代码(我这只是其中一种,还有很多种写法)加壳&amp;多 DEX 注意处理 attach<br></p>', 'https://feilongwl.cn/Public/Uploads/2019-02-21/5c6e602037ce7.png', '1', '44', '1550738196', '1685467936', '4554', '0', '', '0', '1', '', '', '', '1');
INSERT INTO `blog_article` VALUES ('472', '[全套等级代挂]代挂圈子上线了', '<p>我也是看到了近期很多群有需要这种代挂类的业务就果断搭建了一个代挂网站。</p><p><br></p><p>目前的网址为：feilong.66dg.cc<br></p>', 'https://feilongwl.cn/Public/Uploads/2019-03-05/5c7e131d2596b.png', '1', '37', '1551766344', '1685467935', '2508', '0', '', '0', '0', '', '', '', '1');
INSERT INTO `blog_article` VALUES ('474', '苹果iOS 12.4公开越狱工具', '<p>	<span style=\"font-size: 15px;\"><img alt=\"20190820101299499949.jpg\" src=\"https://feilongwl.cn/Public/Uploads/2019-08-20/5d5b87f60c4c1.jpg\" width=\"501\" height=\"841\"><img alt=\"2019082010100979979.jpg\" src=\"https://feilongwl.cn/Public/Uploads/2019-08-20/5d5b87fa1a2d2.jpg\" width=\"595\" height=\"338\"><br></span></p><p><span style=\"font-size: 15px;\">一名名为Pwn20wnd的黑客已经在放出了iPhone的新的公开越狱工具</span> </p><p>	<span style=\"font-size: 15px;\">本次越狱工具并不向下兼容，也就是只支持12.4这个版本，不支持A12设备！<br></span> </p><p>	<span style=\"font-size: 15px;\">支持机型</span> </p><p>	<span style=\"font-size: 15px;\">Phone X</span> </p><p>	<span style=\"font-size: 15px;\">iPhone 8 &amp; 8P</span> </p><p>	<span style=\"font-size: 15px;\">iPhone 7 &amp; 7P</span> </p><p>	<span style=\"font-size: 15px;\">iPhone 6S &amp; 6SP</span> </p><p>	<span style=\"font-size: 15px;\">iPhone SE</span> </p><p>	<span style=\"font-size: 15px;\">iPhone 6 &amp; 6P</span> </p><p>	<span style=\"font-size: 15px;\">iPhone 5s</span> </p><p>	<span style=\"font-size: 15px;\">iPad Air 1,2</span> </p><p>	<span style=\"font-size: 15px;\">iPad (2017)</span> </p><p>	<span style=\"font-size: 15px;\">iPad Mini 2,3,4</span> </p><p>	<span style=\"font-size: 15px;\">iPad Pro 1,2</span> </p><p>	<span style=\"font-size: 15px;\">iPod Touch 6th Gen</span></p><p>	<span style=\"font-size: 15px;\">下载完成后在「设置」-「通用」-「设备管理」点击信任此工具。<br></span> </p><p>	<span style=\"font-size: 15px;\">打开 「 Unc0ver 」软件，点击「 Jailbreak 」，就会开始越狱操作，耐心等待进度条结束。<br></span> </p><p>	<span style=\"font-size: 15px;\">过程中软件可能会闪退或者重启，重新打开「 Unc0ver 」操作即可，直到弹出提示框后点「 OK 」。</span> </p><p>	<span style=\"font-size: 15px;\">完成后如果桌面上出现「 Cydia 」图标，表明你已经成功的越狱，可以添加各种插件源来安装越狱插件。<br></span> </p><p>	<span style=\"font-size: 15px;\">越狱工具地址：<a href=\"https://github.com/pwn20wndstuff/Undecimus/releases\" target=\"_blank\">https://github.com/pwn20wndstuff/Undecimus/releases</a></span> </p><p>（需下载到电脑，用Impactor安装！不会的自行百度下）</p><p>	<span style=\"font-size: 15px;\">第三方下载站：<a href=\"https://next.tweakboxapp.com/\" target=\"_blank\">https://next.tweakboxapp.com/</a></span> </p><p>备用下载地址蓝奏云：<a href=\"https://www.lanzous.com/i5q3rpg\" target=\"_blank\">https://www.lanzous.com/i5q3rpg</a></p><p>最简单的方式就是 用自带浏览器打开蓝奏网盘下载链接下载安装，通用-信任-打开就ok！</p>', 'https://feilongwl.cn/Public/Uploads/2019-08-20/5d5b87ed9659f.jpg', '1', '22', '1566279681', '1685467937', '3166', '0', '', '0', '0', '', '', '', '1');
INSERT INTO `blog_article` VALUES ('475', '2020浅谈Ps4破解版是否值得购买以及常见问题解决', '<p>在2020年7月爆出Ps4 6.72以及7.01系统被破解，后放出了6.72的破解版本。现破解已开卖6.72系统的破解机器。仍然适用于我该文的观点。老游戏玩单机破解无所谓，新游戏还是玩不了的只能正版。国行解锁方法已经失效，目前只可以通过备份方案解决锁服问题。</p><p><br></p><p>PS4相关文章：<a href=\"http://feilongwl.cn/index.php?m=home&amp;c=article&amp;a=index&amp;id=475\" target=\"_blank\">2020浅谈Ps4破解版是否值得购买以及常见问题解决</a>	<br></p><p>PS4相关文章：<a href=\"http://feilongwl.cn/index.php?m=home&amp;c=article&amp;a=index&amp;id=480\" target=\"_blank\">PS4 5.05/6.72/7.02版本破解教程</a></p><p>PS4游戏下载推荐：<a href=\"https://www.52player.top\" target=\"_blank\">吾爱玩家</a><br></p><p><span style=\"font-size: 10.5pt;\"><font><br></font></span></p><hr><p><br>博客因为工作原因搁置很久未更新，最新的一些资讯更新在新浪微博：<a href=\"https://weibo.com/u/5747772673\" target=\"_blank\">飞龙Test的微博</a></p><p><br></p><p>先扫盲。Ps4【PlayStation 4是索尼电脑娱乐公司推出的家用游戏机。是PlayStation游戏机系列的第四代游戏主机，采用AMD Jaguar 8core处理器】</p><p><br></p><p>本篇文章着重介绍个人看法，仅代表个人观点。任何问题可以在博客留言。</p><hr><p><span style=\"font-size: 1.5em; color: rgb(65, 140, 175);\">Ps4版本分类：</span></p><p><br></p><p>Ps4版本可以分为Slim、Pro、厚版11、12（已停产）。其中<span style=\"color: rgb(51, 51, 51); font-size: 16px;\">Slim</span>版和以前的厚板性能是一样的，只是更轻薄，功耗更小。<span style=\"color: rgb(51, 51, 51); font-size: 16px;\">Pro</span>版则是性能升级版，支持4K<span style=\"color: rgb(51, 51, 51); font-size: 16px;\">（前提是家用电视支持4K）</span>。</p><p>分别又对应了国行、港版、以及海外版本。国行的优势为保修，电源线为标准的插头，但是缺点为锁区，Psn商店资源少，不过可以通过特殊的操作方法来切换为不限制版本，具体的操作流程下面会有介绍。</p><p>港版以及国外版的区别在于肯定国内不保修，其次是插头需要用转换器进行转换，优势也很明显不需要解锁的操作，其他均为一样。部分海外版本有手柄按钮位置差异（例如美版所以不太推荐）。国行有了解决方式没有理由不选择国行。</p><p><br></p><hr><p><b><span style=\"color: rgb(227, 55, 55);\">如何解除国行<b style=\"\">Ps4</b>锁区、锁服</span>。只需4个按键即可操作，我也是新手摸索过程中交了智商税，淘宝10块买了解锁方法。国行机器登陆港版账号出现【<span style=\"color: rgb(227, 55, 55);\">无法登陆 您的账号与本主机的出厂设定不兼容</span>】解决方法也如下。</b></p><p><b><br></b></p><p></p><p>操作流程如下：<br></p><p>1.首先更新PS4国行机系统，保证在最新系统下进行操作（目前PS4最新系统7.02）</p><p>2.PS4主界面点击设定—格式化—格式化PS4（不要点快速或者全格式化，只停留在这个有两个选项的PS4格式化界面）</p><p>3.在PS4格式化的界面上，同时按L2+R2+三角+方向键右，持续5-10秒即可成功（无需格式化），PS4国行机变全服机器，可直接登陆外服账号。</p><p>4.成功没任何提示的，自己登陆新追加/注册港服账户即可，没再出现不兼容，可以直接登陆就代表成功了。</p><p><br></p><p></p><p><img alt=\"Screenshot_2020-02-27-10-58-41-367_com.taobao.tao.jpg\" src=\"https://feilongwl.cn/Public/Uploads/2020-02-27/5e5745aad3f73.jpg\" width=\"NaN\"><br></p><p><br></p><hr><p><span style=\"color: rgb(65, 140, 175); font-size: 1.5em;\">Ps4破解版与非破解版的区别</span><br></p><p><br></p><p><b style=\"color: rgb(170, 135, 115);\">破解版：</b></p><p>截止到目前（2020年2月27）目前存在的破解系统停留在版本5.05以及以下均可被破解，最新版本为7.0.2。破解版无法联网，不能升级游戏版本，不能获取奖杯当然也不能登陆PSN。</p><p>我在购买之前想到了是否可以洗白，就是买到破解之后再升级最新版。但是后来发现意义不大，原因是买破解首先就比原版同等机器价格高，第二需要格式化用U盘下载最新固件刷机，但是面临可能被Ban机的风险。<span style=\"color: rgb(65, 140, 175);\"><b>不如某二手平台出掉再买正版机器。二手市场流通非常活跃，只要找个人卖家基本不会出现问题。</b></span></p><p>了解到这些之后，破解版需要折腾，动手能力差的买家可能不会自己去下载游戏还得通过找某宝卖家邮寄硬盘的方式进行，也不太方便。其次，5.05系统可玩的游戏不包含最新的游戏大作，截止到目前可以列举的有荒野大镖客救赎2、漫威蜘蛛侠、七龙珠卡卡罗特等。原因很简单，这些游戏均使用新版本的sdk开发，自然旧版无法打开。优势在于可以免费玩一些单击游戏。</p><p>找破解版可以在pdd、或者某宝搜索，【Ps4 游戏免费】关键词，可以参考看是否有自己喜欢的游戏。</p><p><br></p><p><span style=\"color: rgb(170, 135, 115);\"><b>正版：</b></span></p><p>正版最大的缺陷就是费钱。不过我还是选择了正版的Pro，买了得游戏卡带用收纳盒子摆出来还是很有成就感的。还有奖杯的获得也充满了惊喜。也可以玩线上模式，只要有线上模式的都可以，游戏大部分也都有线上模式的。学生玩家可以在某鱼收游戏玩了再出再换，基本不会亏损很多。还是很值得的。</p><p><br></p><hr><p><span style=\"font-size: 1.5em; color: rgb(65, 140, 175);\">Ps4游戏适合人群</span></p><p><span style=\"font-size: 1.5em; color: rgb(65, 140, 175);\"><br></span></p><p>Ps4的游戏大多偏向于成年玩家，限制级也有很多，这也是大家在注册的时候需要选择港服和解锁的原因。像GTA、巫师3这种游戏国内的商店肯定是不会出现的。Ps4适合时间充裕的个体，游戏大多为单人故事剧情游戏。在双人、家庭游戏方面除了体育、格斗其他基本可数。优质的游戏推荐看过很多《分手厨房2》《小小大星球3》《雷曼传奇》《胖公主历险记》《钠克大冒险2》《GT Sport》《植物大战僵尸系列部分》在众多游戏中了解到的只有这么多值得买的游戏。如果并不是喜欢以上游戏类型的玩家自然不适合买Ps4。可能NS更适合你。</p><p><br></p><hr><p><span style=\"color: rgb(65, 140, 175); font-size: 1.5em;\">结尾</span></p><p>我也是刚刚开始了解的小白，间接也是查了很多资料的总结。后期可能还是更新Switch的相关踩坑的分享。</p><p><br></p><hr><p><img alt=\"wx_camera_1582258178609.jpg\" src=\"https://feilongwl.cn/Public/Uploads/2020-02-27/5e57465bc2355.jpg\" width=\"NaN\"><br></p><p><br></p><p><br></p><p><img alt=\"0AFM39Y[7OZ]6YUM{)N3@I8.png\" src=\"https://feilongwl.cn/Public/Uploads/2020-02-27/5e5742631b950.png\" width=\"1233\"><br></p>', 'https://feilongwl.cn/Public/Uploads/2020-02-27/5e57419bdcac4.jpg', '1', '38', '1582776796', '1685467937', '180214', '0', '', '0', '0', '', '', '', '1');
