INSERT INTO `blog_comment` VALUES ('108', 'sam', '917863430@qq.com', '方法不错，不过动态解析本身会存在一定的限制\r\n    1、需要android运行环境和hook的支持\r\n    2、不同apk混淆的结果可能会不一样，还得人工进行具体分析\r\n    3、只能解密打开打开的页面，需要自己手动打开所有页面才能得到全量\r\n我自己写了一个python工具，可以静态的解密相关的资源，有兴趣可以参考：\r\nhttps://github.com/newdive/uzmap-res', '0', '0', '1588547079', '471', '0');
